VALUES
    ('eps-b2-r-picture-01', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-picture', 'Picture to Word or Sentence', '그림 보고 고르기 3', '다음 그림을 보고 맞는 단어나 문장을 고르십시오.', NULL, NULL, '/api/v1/questions/assets/eps_b2_pic_saw', 75, '[{"id": "A", "text": "톱입니다."}, {"id": "B", "text": "망치입니다."}, {"id": "C", "text": "드라이버입니다."}, {"id": "D", "text": "줄자입니다."}]'::jsonb, '["A"]'::jsonb, '톱 means "saw". 망치 is hammer, 드라이버 is screwdriver, 줄자 is tape measure.', 'easy', ARRAY['EPS_TOPIK Reading', 'Picture to Word or Sentence', 'tools-machines']::text[], 1, TRUE, 'Question: Look at the picture and choose the matching word or sentence. Choices: A. Saw. B. Hammer. C. Screwdriver. D. Tape measure.'),
    ('eps-b2-r-picture-02', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-picture', 'Picture to Word or Sentence', '그림 보고 고르기 4', '다음 그림을 보고 맞는 단어나 문장을 고르십시오.', NULL, NULL, '/api/v1/questions/assets/eps_b2_pic_bowl', 75, '[{"id": "A", "text": "숟가락입니다."}, {"id": "B", "text": "그릇입니다."}, {"id": "C", "text": "칼입니다."}, {"id": "D", "text": "프라이팬입니다."}]'::jsonb, '["B"]'::jsonb, '그릇 means "bowl". 숟가락 is spoon, 칼 is knife, 프라이팬 is frying pan.', 'easy', ARRAY['EPS_TOPIK Reading', 'Picture to Word or Sentence', 'basic-life']::text[], 1, TRUE, 'Question: Look at the picture and choose the matching word or sentence. Choices: A. Spoon. B. Bowl. C. Knife. D. Frying pan.'),
    ('eps-b2-r-picture-03', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-picture', 'Picture to Word or Sentence', '그림 보고 고르기 5', '다음 그림을 보고 맞는 단어나 문장을 고르십시오.', NULL, NULL, '/api/v1/questions/assets/eps_b2_pic_book', 75, '[{"id": "A", "text": "공책입니다."}, {"id": "B", "text": "편지 봉투입니다."}, {"id": "C", "text": "책입니다."}, {"id": "D", "text": "클립입니다."}]'::jsonb, '["C"]'::jsonb, '책 means "book". 공책 is notebook, 편지 봉투 is envelope, 클립 is paper clip.', 'easy', ARRAY['EPS_TOPIK Reading', 'Picture to Word or Sentence', 'job-korean']::text[], 1, TRUE, 'Question: Look at the picture and choose the matching word or sentence. Choices: A. Notebook. B. Envelope. C. Book. D. Paper clip.'),
    ('eps-b2-r-picture-04', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-picture', 'Picture to Word or Sentence', '그림 보고 고르기 6', '다음 그림을 보고 맞는 단어나 문장을 고르십시오.', NULL, NULL, '/api/v1/questions/assets/eps_b2_pic_camera', 75, '[{"id": "A", "text": "충전기입니다."}, {"id": "B", "text": "이어폰입니다."}, {"id": "C", "text": "에어컨입니다."}, {"id": "D", "text": "카메라입니다."}]'::jsonb, '["D"]'::jsonb, '카메라 means "camera". 충전기 is charger, 이어폰 is earphones, 에어컨 is air conditioner.', 'easy', ARRAY['EPS_TOPIK Reading', 'Picture to Word or Sentence', 'basic-life']::text[], 1, TRUE, 'Question: Look at the picture and choose the matching word or sentence. Choices: A. Charger. B. Earphones. C. Air conditioner. D. Camera.'),
