    ('eps-b2-l-sound-46', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-sound', 'Choose What You Heard', '소리 구별 48', '들은 것을 고르십시오.', NULL, '작업', NULL, 75, '[{"id": "A", "text": "직업"}, {"id": "B", "text": "작업"}, {"id": "C", "text": "졸업"}, {"id": "D", "text": "작별"}]'::jsonb, '["B"]'::jsonb, 'You heard 작업 (work task). 직업 is occupation, 졸업 is graduation, 작별 is farewell.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose What You Heard', 'job-korean']::text[], 1, TRUE, 'Audio: Work task. Choices: A. occupation. B. work task. C. graduation. D. farewell.'),
    ('eps-b2-l-sound-47', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-sound', 'Choose What You Heard', '소리 구별 49', '들은 것을 고르십시오.', NULL, '위험', NULL, 75, '[{"id": "A", "text": "시험"}, {"id": "B", "text": "체험"}, {"id": "C", "text": "위험"}, {"id": "D", "text": "위협"}]'::jsonb, '["C"]'::jsonb, 'You heard 위험 (danger). 시험 is exam, 체험 is experience, 위협 is threat.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose What You Heard', 'industrial-safety']::text[], 1, TRUE, 'Audio: Danger. Choices: A. exam. B. experience. C. danger. D. threat.'),
    ('eps-b2-l-sound-48', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-sound', 'Choose What You Heard', '소리 구별 50', '들은 것을 고르십시오.', NULL, '고장', NULL, 75, '[{"id": "A", "text": "고향"}, {"id": "B", "text": "공항"}, {"id": "C", "text": "고생"}, {"id": "D", "text": "고장"}]'::jsonb, '["D"]'::jsonb, 'You heard 고장 (breakdown). 고향 is hometown, 공항 is airport, 고생 is hardship.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose What You Heard', 'tools-machines']::text[], 1, TRUE, 'Audio: Breakdown. Choices: A. hometown. B. airport. C. hardship. D. breakdown.'),
    ('eps-b2-l-response-01', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 3', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 이름이 뭐예요?', NULL, 75, '[{"id": "A", "text": "저는 라주예요."}, {"id": "B", "text": "네, 이름이에요."}, {"id": "C", "text": "한국에서 일해요."}, {"id": "D", "text": "스물여덟 살이에요."}]'::jsonb, '["A"]'::jsonb, '이름이 뭐예요? asks for your name, so the reply gives one.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'basic-life']::text[], 1, TRUE, 'Man: What''s your name? Choices: A. I''m Raju. B. Yes, it''s a name. C. I work in Korea. D. I''m twenty-eight.'),
    ('eps-b2-l-response-02', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 4', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 몇 살이에요?', NULL, 75, '[{"id": "A", "text": "다섯 시예요."}, {"id": "B", "text": "스물다섯 살이에요."}, {"id": "C", "text": "이 층이에요."}, {"id": "D", "text": "다섯 명이에요."}]'::jsonb, '["B"]'::jsonb, '몇 살 asks your age; 살 is the counter for years of age.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'numbers-time']::text[], 1, TRUE, 'Woman: How old are you? Choices: A. It''s five o''clock. B. I''m twenty-five. C. It''s the second floor. D. There are five people.'),
    ('eps-b2-l-response-03', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 5', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 한국에 언제 왔어요?', NULL, 75, '[{"id": "A", "text": "비행기로 왔어요."}, {"id": "B", "text": "친구와 같이 왔어요."}, {"id": "C", "text": "작년 삼월에 왔어요."}, {"id": "D", "text": "네팔에서 왔어요."}]'::jsonb, '["C"]'::jsonb, '언제 asks when, so the answer is a time: 작년 삼월.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'basic-life']::text[], 1, TRUE, 'Man: When did you come to Korea? Choices: A. I came by plane. B. I came with a friend. C. I came in March last year. D. I came from Nepal.'),
    ('eps-b2-l-response-04', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 6', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 주말에 보통 뭐 해요?', NULL, 75, '[{"id": "A", "text": "주말이 아니에요."}, {"id": "B", "text": "토요일이에요."}, {"id": "C", "text": "회사가 멀어요."}, {"id": "D", "text": "친구를 만나거나 쉬어요."}]'::jsonb, '["D"]'::jsonb, '뭐 해요 asks what you do; meeting friends or resting answers it.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'daily-life']::text[], 1, TRUE, 'Woman: What do you usually do at weekends? Choices: A. It isn''t the weekend. B. It''s Saturday. C. The company is far away. D. I meet friends or rest.'),
    ('eps-b2-l-response-05', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 7', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 점심 먹었어요?', NULL, 75, '[{"id": "A", "text": "네, 방금 먹었어요."}, {"id": "B", "text": "점심은 열두 시예요."}, {"id": "C", "text": "식당이 커요."}, {"id": "D", "text": "네, 맛있게 드세요."}]'::jsonb, '["A"]'::jsonb, 'A yes-or-no question about eating: 네, 방금 먹었어요.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'daily-life']::text[], 1, TRUE, 'Man: Have you had lunch? Choices: A. Yes, I''ve just eaten. B. Lunch is at twelve. C. The canteen is big. D. Yes, enjoy your meal.'),
    ('eps-b2-l-response-06', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 8', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 이 일은 처음 해 봐요?', NULL, 75, '[{"id": "A", "text": "네, 첫 번째 층이에요."}, {"id": "B", "text": "네, 처음이라서 잘 몰라요."}, {"id": "C", "text": "처음 뵙겠습니다."}, {"id": "D", "text": "일이 끝났어요."}]'::jsonb, '["B"]'::jsonb, '처음 해 봐요? asks whether you have done it before.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'job-korean']::text[], 1, TRUE, 'Woman: Is this your first time doing this work? Choices: A. Yes, it''s the first floor. B. Yes, it''s my first time, so I don''t know it well. C. Nice to meet you. D. The work is finished.'),
    ('eps-b2-l-response-07', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 9', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 집이 회사에서 멀어요?', NULL, 75, '[{"id": "A", "text": "네, 집이 커요."}, {"id": "B", "text": "회사가 좋아요."}, {"id": "C", "text": "아니요, 걸어서 십 분쯤 걸려요."}, {"id": "D", "text": "집에 가요."}]'::jsonb, '["C"]'::jsonb, '멀어요? asks about distance; ten minutes on foot answers it.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'basic-life']::text[], 1, TRUE, 'Man: Is your home far from the company? Choices: A. Yes, my home is big. B. The company is good. C. No, it takes about ten minutes on foot. D. I''m going home.'),
    ('eps-b2-l-response-08', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 10', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 무슨 음식을 좋아해요?', NULL, 75, '[{"id": "A", "text": "음식이 많아요."}, {"id": "B", "text": "식당에 가요."}, {"id": "C", "text": "네, 좋아해요."}, {"id": "D", "text": "불고기를 좋아해요."}]'::jsonb, '["D"]'::jsonb, '무슨 asks which one, so a yes is not enough: name a food.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'daily-life']::text[], 1, TRUE, 'Woman: What food do you like? Choices: A. There''s a lot of food. B. I''m going to a restaurant. C. Yes, I like it. D. I like bulgogi.'),
    ('eps-b2-l-response-09', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 11', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 어디가 아파요?', NULL, 75, '[{"id": "A", "text": "머리가 아파요."}, {"id": "B", "text": "병원에 있어요."}, {"id": "C", "text": "어제 아팠어요."}, {"id": "D", "text": "약을 먹었어요."}]'::jsonb, '["A"]'::jsonb, '어디가 asks which part of the body hurts.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'public-services']::text[], 1, TRUE, 'Man: Where does it hurt? Choices: A. I have a headache. B. I''m at the hospital. C. I was ill yesterday. D. I took some medicine.'),
    ('eps-b2-l-response-10', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 12', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 이 상자를 어디에 둘까요?', NULL, 75, '[{"id": "A", "text": "상자가 무거워요."}, {"id": "B", "text": "저쪽 선반 위에 두세요."}, {"id": "C", "text": "네, 두 개 있어요."}, {"id": "D", "text": "상자를 샀어요."}]'::jsonb, '["B"]'::jsonb, '어디에 둘까요? asks where to put it, so the reply names a place.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'job-korean']::text[], 1, TRUE, 'Woman: Where shall I put this box? Choices: A. The box is heavy. B. Put it on the shelf over there. C. Yes, there are two. D. I bought a box.'),
    ('eps-b2-l-response-11', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 13', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 내일 몇 시까지 출근해야 해요?', NULL, 75, '[{"id": "A", "text": "버스를 타고 오세요."}, {"id": "B", "text": "내일은 화요일이에요."}, {"id": "C", "text": "여덟 시까지 오세요."}, {"id": "D", "text": "공장으로 오세요."}]'::jsonb, '["C"]'::jsonb, '몇 시까지 asks by what time.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'workplace-culture']::text[], 1, TRUE, 'Man: What time do I have to be at work tomorrow? Choices: A. Come by bus. B. Tomorrow is Tuesday. C. Come by eight. D. Come to the factory.'),
    ('eps-b2-l-response-12', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 14', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 고향에 가족이 몇 명 있어요?', NULL, 75, '[{"id": "A", "text": "고향은 베트남이에요."}, {"id": "B", "text": "가족을 사랑해요."}, {"id": "C", "text": "세 시에 전화해요."}, {"id": "D", "text": "부모님하고 동생, 세 명이 있어요."}]'::jsonb, '["D"]'::jsonb, '몇 명 asks how many people.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'basic-life']::text[], 1, TRUE, 'Woman: How many family members do you have back home? Choices: A. My hometown is in Vietnam. B. I love my family. C. I call at three. D. Three – my parents and my younger sibling.'),
    ('eps-b2-l-response-13', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 15', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 이 근처에 은행이 있어요?', NULL, 75, '[{"id": "A", "text": "네, 우체국 옆에 있어요."}, {"id": "B", "text": "네, 돈이 있어요."}, {"id": "C", "text": "은행에서 일해요."}, {"id": "D", "text": "돈을 찾았어요."}]'::jsonb, '["A"]'::jsonb, 'The question is whether a bank is nearby; the reply says where it is.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'public-services']::text[], 1, TRUE, 'Man: Is there a bank near here? Choices: A. Yes, it''s next to the post office. B. Yes, I have money. C. I work at a bank. D. I took out some money.'),
    ('eps-b2-l-response-14', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 16', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 휴가 때 뭐 할 거예요?', NULL, 75, '[{"id": "A", "text": "휴가가 삼 일이에요."}, {"id": "B", "text": "고향에 다녀올 거예요."}, {"id": "C", "text": "휴가 신청서예요."}, {"id": "D", "text": "어제 쉬었어요."}]'::jsonb, '["B"]'::jsonb, '뭐 할 거예요 asks about a plan.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'workplace-culture']::text[], 1, TRUE, 'Woman: What will you do on your holiday? Choices: A. The holiday is three days. B. I''ll go home for a visit. C. It''s a leave form. D. I rested yesterday.'),
    ('eps-b2-l-response-15', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 17', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 한국 생활이 어때요?', NULL, 75, '[{"id": "A", "text": "한국에 살아요."}, {"id": "B", "text": "한국 사람이에요."}, {"id": "C", "text": "조금 힘들지만 재미있어요."}, {"id": "D", "text": "생활비를 보냈어요."}]'::jsonb, '["C"]'::jsonb, '어때요? asks how something is, so the reply describes it.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'basic-life']::text[], 1, TRUE, 'Man: How is life in Korea? Choices: A. I live in Korea. B. I''m Korean. C. It''s a bit hard, but it''s fun. D. I sent living expenses.'),
    ('eps-b2-l-response-16', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 18', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 이 옷 얼마예요?', NULL, 75, '[{"id": "A", "text": "옷이 예뻐요."}, {"id": "B", "text": "두 벌 있어요."}, {"id": "C", "text": "시장에서 샀어요."}, {"id": "D", "text": "이만 원이에요."}]'::jsonb, '["D"]'::jsonb, '얼마예요? asks the price.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'daily-life']::text[], 1, TRUE, 'Woman: How much is this? Choices: A. The clothes are pretty. B. There are two. C. I bought it at the market. D. It''s twenty thousand won.'),
    ('eps-b2-l-response-17', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 19', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 무엇을 도와 드릴까요?', NULL, 75, '[{"id": "A", "text": "통장을 만들고 싶어요."}, {"id": "B", "text": "네, 도와 드릴게요."}, {"id": "C", "text": "저는 은행원이에요."}, {"id": "D", "text": "도움이 많아요."}]'::jsonb, '["A"]'::jsonb, 'Staff ask this when you come in; the reply says what you need.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'public-services']::text[], 1, TRUE, 'Man: What can I help you with? Choices: A. I''d like to open a bank account. B. Yes, I''ll help you. C. I''m a bank clerk. D. There''s a lot of help.'),
    ('eps-b2-l-response-18', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 20', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 작업복은 어디에서 갈아입어요?', NULL, 75, '[{"id": "A", "text": "작업복이 커요."}, {"id": "B", "text": "이 층 탈의실에서 갈아입으세요."}, {"id": "C", "text": "아침에 입어요."}, {"id": "D", "text": "파란색이에요."}]'::jsonb, '["B"]'::jsonb, '어디에서 asks where.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'job-korean']::text[], 1, TRUE, 'Woman: Where do I change into my work clothes? Choices: A. The work clothes are big. B. Change in the changing room on the second floor. C. I put them on in the morning. D. They''re blue.'),
    ('eps-b2-l-response-19', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 21', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 오늘 야근할 수 있어요?', NULL, 75, '[{"id": "A", "text": "야근이 많아요."}, {"id": "B", "text": "밤이에요."}, {"id": "C", "text": "네, 할 수 있어요."}, {"id": "D", "text": "야근 수당이에요."}]'::jsonb, '["C"]'::jsonb, '할 수 있어요? asks whether you can; 네, 할 수 있어요 answers it.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'workplace-culture']::text[], 1, TRUE, 'Man: Can you work overtime tonight? Choices: A. There''s a lot of overtime. B. It''s night. C. Yes, I can. D. It''s overtime pay.'),
    ('eps-b2-l-response-20', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 22', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 기숙사 방은 몇 명이 같이 써요?', NULL, 75, '[{"id": "A", "text": "방이 깨끗해요."}, {"id": "B", "text": "이 층에 있어요."}, {"id": "C", "text": "두 시에 써요."}, {"id": "D", "text": "두 명이 같이 써요."}]'::jsonb, '["D"]'::jsonb, '몇 명 asks how many people.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'basic-life']::text[], 1, TRUE, 'Woman: How many people share a dormitory room? Choices: A. The room is clean. B. It''s on the second floor. C. I use it at two. D. Two people share it.'),
    ('eps-b2-l-response-21', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 23', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 이 기계 사용법을 알아요?', NULL, 75, '[{"id": "A", "text": "아니요, 한 번 가르쳐 주세요."}, {"id": "B", "text": "기계가 비싸요."}, {"id": "C", "text": "네, 기계예요."}, {"id": "D", "text": "기계를 샀어요."}]'::jsonb, '["A"]'::jsonb, '사용법을 알아요? asks whether you know how to use it.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'tools-machines']::text[], 1, TRUE, 'Man: Do you know how to use this machine? Choices: A. No, please show me once. B. The machine is expensive. C. Yes, it''s a machine. D. I bought a machine.'),
    ('eps-b2-l-response-22', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 24', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 무슨 일을 해요?', NULL, 75, '[{"id": "A", "text": "일이 많아요."}, {"id": "B", "text": "공장에서 부품을 만들어요."}, {"id": "C", "text": "아홉 시에 일해요."}, {"id": "D", "text": "일요일에 쉬어요."}]'::jsonb, '["B"]'::jsonb, '무슨 일 asks what job you do.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'job-korean']::text[], 1, TRUE, 'Woman: What work do you do? Choices: A. There''s a lot of work. B. I make parts in a factory. C. I work at nine. D. I rest on Sundays.'),
    ('eps-b2-l-response-23', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 25', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 왜 늦었어요?', NULL, 75, '[{"id": "A", "text": "아홉 시에 왔어요."}, {"id": "B", "text": "늦게 자요."}, {"id": "C", "text": "버스가 늦게 와서 늦었어요."}, {"id": "D", "text": "내일 올게요."}]'::jsonb, '["C"]'::jsonb, '왜 asks for a reason; -아서/어서 gives one.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'workplace-culture']::text[], 1, TRUE, 'Man: Why are you late? Choices: A. I came at nine. B. I go to bed late. C. The bus came late, so I was late. D. I''ll come tomorrow.'),
    ('eps-b2-l-response-24', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 26', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 전화번호가 몇 번이에요?', NULL, 75, '[{"id": "A", "text": "휴대폰이 있어요."}, {"id": "B", "text": "세 번 전화했어요."}, {"id": "C", "text": "전화를 받으세요."}, {"id": "D", "text": "공일공 일이삼사 오육칠팔이에요."}]'::jsonb, '["D"]'::jsonb, 'Phone numbers are read digit by digit in Sino-Korean numbers.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'numbers-time']::text[], 1, TRUE, 'Woman: What''s your phone number? Choices: A. I have a mobile phone. B. I called three times. C. Please answer the phone. D. It''s 010-1234-5678.'),
    ('eps-b2-l-response-25', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 27', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 생일이 언제예요?', NULL, 75, '[{"id": "A", "text": "시월 이십 일이에요."}, {"id": "B", "text": "스물다섯 살이에요."}, {"id": "C", "text": "케이크를 먹어요."}, {"id": "D", "text": "생일 축하해요."}]'::jsonb, '["A"]'::jsonb, '언제 asks for a date: 시월 이십 일.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'numbers-time']::text[], 1, TRUE, 'Man: When is your birthday? Choices: A. It''s the twentieth of October. B. I''m twenty-five. C. I eat cake. D. Happy birthday.'),
    ('eps-b2-l-response-26', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 28', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 커피 마실래요?', NULL, 75, '[{"id": "A", "text": "커피숍이에요."}, {"id": "B", "text": "네, 좋아요. 고마워요."}, {"id": "C", "text": "커피를 샀어요."}, {"id": "D", "text": "커피가 검은색이에요."}]'::jsonb, '["B"]'::jsonb, 'An offer: accept or decline it.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'daily-life']::text[], 1, TRUE, 'Woman: Would you like some coffee? Choices: A. It''s a coffee shop. B. Yes, please. Thank you. C. I bought coffee. D. Coffee is black.'),
    ('eps-b2-l-response-27', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 29', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 한국어를 어디에서 배웠어요?', NULL, 75, '[{"id": "A", "text": "한국어가 어려워요."}, {"id": "B", "text": "일 년 배웠어요."}, {"id": "C", "text": "고향에 있는 학원에서 배웠어요."}, {"id": "D", "text": "한국어 책이에요."}]'::jsonb, '["C"]'::jsonb, '어디에서 asks where, not how long.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'daily-life']::text[], 1, TRUE, 'Man: Where did you learn Korean? Choices: A. Korean is difficult. B. I learned it for a year. C. At a language school back home. D. It''s a Korean book.'),
    ('eps-b2-l-response-28', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 30', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 이번 달 월급 받았어요?', NULL, 75, '[{"id": "A", "text": "월급이 많아요."}, {"id": "B", "text": "은행에 가요."}, {"id": "C", "text": "월급날이에요?"}, {"id": "D", "text": "네, 어제 받았어요."}]'::jsonb, '["D"]'::jsonb, 'A yes-or-no question about getting paid.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'job-korean']::text[], 1, TRUE, 'Woman: Have you been paid this month? Choices: A. The pay is good. B. I''m going to the bank. C. Is it payday? D. Yes, I got it yesterday.'),
    ('eps-b2-l-response-29', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 31', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 어떤 운동을 좋아해요?', NULL, 75, '[{"id": "A", "text": "축구를 좋아해요."}, {"id": "B", "text": "운동장에 가요."}, {"id": "C", "text": "매일 해요."}, {"id": "D", "text": "운동화를 샀어요."}]'::jsonb, '["A"]'::jsonb, '어떤 asks which one, so name a sport.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'daily-life']::text[], 1, TRUE, 'Man: Which sport do you like? Choices: A. I like football. B. I''m going to the sports ground. C. I do it every day. D. I bought trainers.'),
    ('eps-b2-l-response-30', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 32', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 이 버스 시청에 가요?', NULL, 75, '[{"id": "A", "text": "버스가 커요."}, {"id": "B", "text": "아니요, 십오 번 버스를 타세요."}, {"id": "C", "text": "시청에서 일해요."}, {"id": "D", "text": "버스비가 천오백 원이에요."}]'::jsonb, '["B"]'::jsonb, 'The question is whether this bus goes there.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'public-services']::text[], 1, TRUE, 'Woman: Does this bus go to City Hall? Choices: A. The bus is big. B. No, take the number 15 bus. C. I work at City Hall. D. The fare is 1,500 won.'),
    ('eps-b2-l-response-31', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 33', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 손을 다쳤어요?', NULL, 75, '[{"id": "A", "text": "손이 커요."}, {"id": "B", "text": "장갑을 샀어요."}, {"id": "C", "text": "네, 칼에 조금 베였어요."}, {"id": "D", "text": "손을 씻어요."}]'::jsonb, '["C"]'::jsonb, 'A yes-or-no question about an injury.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'industrial-safety']::text[], 1, TRUE, 'Man: Have you hurt your hand? Choices: A. My hands are big. B. I bought gloves. C. Yes, I cut it a little on a knife. D. I wash my hands.'),
    ('eps-b2-l-response-32', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 34', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 여기에서 사진을 찍어도 돼요?', NULL, 75, '[{"id": "A", "text": "사진이 예뻐요."}, {"id": "B", "text": "카메라가 있어요."}, {"id": "C", "text": "어제 찍었어요."}, {"id": "D", "text": "아니요, 여기에서는 찍으면 안 돼요."}]'::jsonb, '["D"]'::jsonb, '-아도/어도 돼요? asks permission; -으면 안 돼요 refuses it.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'public-services']::text[], 1, TRUE, 'Woman: May I take photos here? Choices: A. The photo is pretty. B. I have a camera. C. I took them yesterday. D. No, you can''t take photos here.'),
    ('eps-b2-l-response-33', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 35', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 밖에 날씨가 어때요?', NULL, 75, '[{"id": "A", "text": "비가 오고 추워요."}, {"id": "B", "text": "날씨가 있어요."}, {"id": "C", "text": "우산이에요."}, {"id": "D", "text": "내일이에요."}]'::jsonb, '["A"]'::jsonb, '어때요? asks what it is like.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'daily-life']::text[], 1, TRUE, 'Man: What''s the weather like outside? Choices: A. It''s raining and cold. B. There is weather. C. It''s an umbrella. D. It''s tomorrow.'),
    ('eps-b2-l-response-34', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 36', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 뭘 드릴까요?', NULL, 75, '[{"id": "A", "text": "맛있게 드세요."}, {"id": "B", "text": "김치찌개 하나 주세요."}, {"id": "C", "text": "식당이 멀어요."}, {"id": "D", "text": "저는 손님이에요."}]'::jsonb, '["B"]'::jsonb, 'Staff at a restaurant ask what you want; order something.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'daily-life']::text[], 1, TRUE, 'Woman: What can I get you? Choices: A. Enjoy your meal. B. One kimchi stew, please. C. The restaurant is far. D. I''m a customer.'),
    ('eps-b2-l-response-35', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 37', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 회의는 몇 층에서 해요?', NULL, 75, '[{"id": "A", "text": "세 시에 해요."}, {"id": "B", "text": "회의가 길어요."}, {"id": "C", "text": "삼 층 회의실에서 해요."}, {"id": "D", "text": "계단으로 가요."}]'::jsonb, '["C"]'::jsonb, '몇 층 asks which floor; floors use Sino-Korean numbers.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'workplace-culture']::text[], 1, TRUE, 'Man: Which floor is the meeting on? Choices: A. At three. B. The meeting is long. C. In the meeting room on the third floor. D. I take the stairs.'),
    ('eps-b2-l-response-36', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 38', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 어제 왜 결근했어요?', NULL, 75, '[{"id": "A", "text": "어제는 월요일이었어요."}, {"id": "B", "text": "오늘 왔어요."}, {"id": "C", "text": "결근하지 마세요."}, {"id": "D", "text": "열이 많이 나서 못 왔어요."}]'::jsonb, '["D"]'::jsonb, '왜 asks for the reason.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'workplace-culture']::text[], 1, TRUE, 'Woman: Why were you absent yesterday? Choices: A. Yesterday was Monday. B. I came today. C. Don''t be absent. D. I had a high fever, so I couldn''t come.'),
    ('eps-b2-l-response-37', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 39', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 이 서류 어디에 사인해요?', NULL, 75, '[{"id": "A", "text": "맨 아래에 사인하세요."}, {"id": "B", "text": "볼펜으로 해요."}, {"id": "C", "text": "서류가 많아요."}, {"id": "D", "text": "내일 주세요."}]'::jsonb, '["A"]'::jsonb, '어디에 asks where, not with what.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'laws-systems']::text[], 1, TRUE, 'Man: Where on this form do I sign? Choices: A. Sign at the very bottom. B. With a pen. C. There are a lot of forms. D. Give it to me tomorrow.'),
    ('eps-b2-l-response-38', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 40', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 같이 저녁 먹을까요?', NULL, 75, '[{"id": "A", "text": "저녁이 맛있어요."}, {"id": "B", "text": "좋아요. 몇 시에 만날까요?"}, {"id": "C", "text": "저는 식당이에요."}, {"id": "D", "text": "아침을 먹었어요."}]'::jsonb, '["B"]'::jsonb, '-을까요? suggests doing something together; accept and plan.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'daily-life']::text[], 1, TRUE, 'Woman: Shall we have dinner together? Choices: A. Dinner is tasty. B. Sure. What time shall we meet? C. I am a restaurant. D. I had breakfast.'),
    ('eps-b2-l-response-39', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 41', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 이 약은 언제 먹어요?', NULL, 75, '[{"id": "A", "text": "약국에서 샀어요."}, {"id": "B", "text": "약이 써요."}, {"id": "C", "text": "하루에 세 번 식후에 드세요."}, {"id": "D", "text": "감기약이에요."}]'::jsonb, '["C"]'::jsonb, '언제 asks when: three times a day, after meals.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'public-services']::text[], 1, TRUE, 'Man: When do I take this medicine? Choices: A. I bought it at the pharmacy. B. The medicine is bitter. C. Take it three times a day after meals. D. It''s cold medicine.'),
    ('eps-b2-l-response-40', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 42', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 고향 음식이 그립지 않아요?', NULL, 75, '[{"id": "A", "text": "고향이 멀어요."}, {"id": "B", "text": "음식을 만들어요."}, {"id": "C", "text": "한국 음식이에요."}, {"id": "D", "text": "네, 가끔 많이 생각나요."}]'::jsonb, '["D"]'::jsonb, 'The question asks how you feel about home food.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'korean-culture']::text[], 1, TRUE, 'Woman: Don''t you miss the food back home? Choices: A. My hometown is far away. B. I make food. C. It''s Korean food. D. Yes, I often think of it.'),
    ('eps-b2-l-response-41', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 43', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 짐이 많네요. 도와 드릴까요?', NULL, 75, '[{"id": "A", "text": "네, 고맙습니다."}, {"id": "B", "text": "짐을 쌌어요."}, {"id": "C", "text": "네, 도와 드릴게요."}, {"id": "D", "text": "짐이 세 개 있어요."}]'::jsonb, '["A"]'::jsonb, 'Someone offers help; thank them. 도와 드릴게요 is what the helper says.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'daily-life']::text[], 1, TRUE, 'Man: You''ve got a lot of bags. Shall I help you? Choices: A. Yes, thank you. B. I packed my bags. C. Yes, I''ll help you. D. There are three bags.'),
    ('eps-b2-l-response-42', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 44', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 퇴근 후에 보통 뭐 해요?', NULL, 75, '[{"id": "A", "text": "여섯 시에 퇴근해요."}, {"id": "B", "text": "기숙사에서 한국어를 공부해요."}, {"id": "C", "text": "퇴근이 늦어요."}, {"id": "D", "text": "회사에서 일해요."}]'::jsonb, '["B"]'::jsonb, '후에 means after: what you do once work is over.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'daily-life']::text[], 1, TRUE, 'Woman: What do you usually do after work? Choices: A. I finish work at six. B. I study Korean in the dormitory. C. I finish late. D. I work at the company.'),
    ('eps-b2-l-response-43', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 45', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 이 장갑 누구 거예요?', NULL, 75, '[{"id": "A", "text": "장갑이 두 개예요."}, {"id": "B", "text": "장갑을 끼세요."}, {"id": "C", "text": "제 거예요. 고마워요."}, {"id": "D", "text": "하얀색이에요."}]'::jsonb, '["C"]'::jsonb, '누구 거 asks whose.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'industrial-safety']::text[], 1, TRUE, 'Man: Whose gloves are these? Choices: A. There are two gloves. B. Put your gloves on. C. They''re mine. Thanks. D. They''re white.'),
    ('eps-b2-l-response-44', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 46', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 비자가 언제까지예요?', NULL, 75, '[{"id": "A", "text": "비자를 받았어요."}, {"id": "B", "text": "출입국 사무소예요."}, {"id": "C", "text": "삼 년 일했어요."}, {"id": "D", "text": "내년 오월까지예요."}]'::jsonb, '["D"]'::jsonb, '언제까지 asks for the end date.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'laws-systems']::text[], 1, TRUE, 'Woman: Until when is your visa valid? Choices: A. I got my visa. B. It''s the immigration office. C. I worked for three years. D. Until May next year.'),
    ('eps-b2-l-response-45', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 47', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 지금 시간 있어요?', NULL, 75, '[{"id": "A", "text": "네, 무슨 일이에요?"}, {"id": "B", "text": "지금 세 시예요."}, {"id": "C", "text": "시계가 있어요."}, {"id": "D", "text": "시간이 빨라요."}]'::jsonb, '["A"]'::jsonb, '시간 있어요? asks if you are free, not what time it is.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'daily-life']::text[], 1, TRUE, 'Man: Have you got a moment now? Choices: A. Yes, what is it? B. It''s three o''clock now. C. I have a watch. D. Time is fast.'),
    ('eps-b2-l-response-46', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 48', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 기숙사 와이파이 비밀번호 알아요?', NULL, 75, '[{"id": "A", "text": "와이파이가 빨라요."}, {"id": "B", "text": "네, 문 옆에 붙어 있어요."}, {"id": "C", "text": "휴대폰이 없어요."}, {"id": "D", "text": "비밀이에요."}]'::jsonb, '["B"]'::jsonb, 'The question asks whether you know the password.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'basic-life']::text[], 1, TRUE, 'Woman: Do you know the dormitory Wi-Fi password? Choices: A. The Wi-Fi is fast. B. Yes, it''s stuck up by the door. C. I don''t have a mobile. D. It''s a secret.'),
    ('eps-b2-l-response-47', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 49', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '남: 누구하고 같이 살아요?', NULL, 75, '[{"id": "A", "text": "기숙사에 살아요."}, {"id": "B", "text": "삼 년 살았어요."}, {"id": "C", "text": "동료 두 명하고 같이 살아요."}, {"id": "D", "text": "혼자 왔어요?"}]'::jsonb, '["C"]'::jsonb, '누구하고 asks who with, so name the people.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'basic-life']::text[], 1, TRUE, 'Man: Who do you live with? Choices: A. I live in the dormitory. B. I''ve lived here three years. C. I live with two co-workers. D. Did you come alone?'),
    ('eps-b2-l-response-48', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-response', 'Choose the Right Reply', '대답 고르기 50', '다음을 듣고 질문에 알맞은 대답을 고르십시오.', NULL, '여: 오늘 기분이 어때요?', NULL, 75, '[{"id": "A", "text": "오늘은 금요일이에요."}, {"id": "B", "text": "기분이 있어요."}, {"id": "C", "text": "날씨예요."}, {"id": "D", "text": "월급날이라서 기분이 좋아요."}]'::jsonb, '["D"]'::jsonb, '기분이 어때요? asks how you feel.', 'easy', ARRAY['EPS_TOPIK Listening', 'Choose the Right Reply', 'daily-life']::text[], 1, TRUE, 'Woman: How are you feeling today? Choices: A. Today is Friday. B. There is a mood. C. It''s the weather. D. It''s payday, so I''m in a good mood.'),
    ('eps-b2-l-next-01', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 3', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 바닥이 미끄러우니까 뛰지 마세요.', NULL, 75, '[{"id": "A", "text": "네, 천천히 걸을게요."}, {"id": "B", "text": "네, 빨리 뛸게요."}, {"id": "C", "text": "바닥을 샀어요."}, {"id": "D", "text": "미끄럼틀이 좋아요."}]'::jsonb, '["A"]'::jsonb, 'A warning not to run; the reply agrees to walk slowly.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'industrial-safety']::text[], 1, TRUE, 'Man: The floor is slippery, so don''t run. Choices: A. OK, I''ll walk slowly. B. OK, I''ll run fast. C. I bought a floor. D. I like slides.'),
    ('eps-b2-l-next-02', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 4', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 내일은 공장 청소가 있어서 일찍 와야 해요.', NULL, 75, '[{"id": "A", "text": "오늘 청소했어요."}, {"id": "B", "text": "알겠습니다. 일찍 올게요."}, {"id": "C", "text": "늦게 올게요."}, {"id": "D", "text": "공장이 커요."}]'::jsonb, '["B"]'::jsonb, 'Asked to come early, the reply agrees: 일찍 올게요.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'workplace-culture']::text[], 1, TRUE, 'Woman: We''re cleaning the factory tomorrow, so you need to come early. Choices: A. I cleaned today. B. Understood. I''ll come early. C. I''ll come late. D. The factory is big.'),
    ('eps-b2-l-next-03', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 5', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 이 상자는 무거우니까 두 사람이 같이 드세요.', NULL, 75, '[{"id": "A", "text": "혼자 들게요."}, {"id": "B", "text": "상자가 작아요."}, {"id": "C", "text": "네, 동료를 불러서 같이 들게요."}, {"id": "D", "text": "상자를 열었어요."}]'::jsonb, '["C"]'::jsonb, 'The instruction is to lift it together, so call a co-worker.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'industrial-safety']::text[], 1, TRUE, 'Man: This box is heavy, so lift it with two people. Choices: A. I''ll lift it on my own. B. The box is small. C. OK, I''ll get a co-worker and lift it together. D. I opened the box.'),
    ('eps-b2-l-next-04', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 6', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 감기에 걸렸으면 오늘은 일찍 들어가서 쉬세요.', NULL, 75, '[{"id": "A", "text": "감기가 좋아요."}, {"id": "B", "text": "오늘은 야근할게요."}, {"id": "C", "text": "일찍 일어났어요."}, {"id": "D", "text": "감사합니다. 약 먹고 푹 쉴게요."}]'::jsonb, '["D"]'::jsonb, 'Told to rest, thank them and say you will.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'workplace-culture']::text[], 1, TRUE, 'Woman: If you''ve got a cold, go home early today and rest. Choices: A. I like colds. B. I''ll do overtime today. C. I got up early. D. Thank you. I''ll take some medicine and get a good rest.'),
    ('eps-b2-l-next-05', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 7', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 다음 주 월요일부터 작업 시간이 바뀝니다.', NULL, 75, '[{"id": "A", "text": "몇 시부터 몇 시까지로 바뀌어요?"}, {"id": "B", "text": "월요일이 좋아요."}, {"id": "C", "text": "지난주에 일했어요."}, {"id": "D", "text": "시간이 없어요."}]'::jsonb, '["A"]'::jsonb, 'News of a change: ask what the new hours are.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'workplace-culture']::text[], 1, TRUE, 'Man: From next Monday, working hours are changing. Choices: A. What will the new hours be? B. I like Mondays. C. I worked last week. D. I have no time.'),
    ('eps-b2-l-next-06', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 8', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 기계에서 이상한 소리가 나요.', NULL, 75, '[{"id": "A", "text": "소리가 좋아요."}, {"id": "B", "text": "그럼 기계를 끄고 반장님께 말씀드리세요."}, {"id": "C", "text": "노래를 불러요."}, {"id": "D", "text": "기계를 샀어요."}]'::jsonb, '["B"]'::jsonb, 'A strange noise means a fault: stop the machine and report it.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'tools-machines']::text[], 1, TRUE, 'Woman: The machine is making a strange noise. Choices: A. It sounds nice. B. Then switch it off and tell the team leader. C. I''m singing. D. I bought a machine.'),
    ('eps-b2-l-next-07', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 9', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 이번 주말에 회사 체육 대회가 있어요.', NULL, 75, '[{"id": "A", "text": "주말에 일했어요."}, {"id": "B", "text": "체육관이 멀어요."}, {"id": "C", "text": "그래요? 저도 축구 경기에 나가고 싶어요."}, {"id": "D", "text": "회사가 커요."}]'::jsonb, '["C"]'::jsonb, 'News of an event: show interest in taking part.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'workplace-culture']::text[], 1, TRUE, 'Man: There''s a company sports day this weekend. Choices: A. I worked at the weekend. B. The gym is far. C. Really? I''d like to play in the football match. D. The company is big.'),
    ('eps-b2-l-next-08', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 10', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 이 서류는 내일까지 꼭 내야 해요.', NULL, 75, '[{"id": "A", "text": "서류가 하얗네요."}, {"id": "B", "text": "다음 달에 낼게요."}, {"id": "C", "text": "서류를 읽어요."}, {"id": "D", "text": "네, 오늘 써서 내일 아침에 드릴게요."}]'::jsonb, '["D"]'::jsonb, 'A deadline: promise to meet it.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'laws-systems']::text[], 1, TRUE, 'Woman: This form must be handed in by tomorrow. Choices: A. The form is white. B. I''ll hand it in next month. C. I''m reading a form. D. OK, I''ll fill it in today and give it to you tomorrow morning.'),
    ('eps-b2-l-next-09', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 11', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 길이 막혀서 조금 늦을 것 같아요.', NULL, 75, '[{"id": "A", "text": "괜찮아요. 천천히 조심해서 오세요."}, {"id": "B", "text": "길이 넓어요."}, {"id": "C", "text": "일찍 왔어요."}, {"id": "D", "text": "막혀서 좋아요."}]'::jsonb, '["A"]'::jsonb, 'Someone will be late; reassure them.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'daily-life']::text[], 1, TRUE, 'Man: The traffic''s bad, so I think I''ll be a little late. Choices: A. That''s fine. Take your time and come safely. B. The road is wide. C. I came early. D. I''m glad it''s jammed.'),
    ('eps-b2-l-next-10', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 12', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 오늘 저녁에 회식이 있는데 같이 가요.', NULL, 75, '[{"id": "A", "text": "저녁을 만들어요."}, {"id": "B", "text": "좋아요. 어디에서 해요?"}, {"id": "C", "text": "어제 갔어요."}, {"id": "D", "text": "회사에 가요."}]'::jsonb, '["B"]'::jsonb, 'An invitation: accept and ask where.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'workplace-culture']::text[], 1, TRUE, 'Woman: There''s a staff dinner tonight. Let''s go together. Choices: A. I''m making dinner. B. Sure. Where is it? C. I went yesterday. D. I''m going to the company.'),
    ('eps-b2-l-next-11', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 13', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 냉장고에 있는 우유는 제 거예요.', NULL, 75, '[{"id": "A", "text": "냉장고가 커요."}, {"id": "B", "text": "우유가 하얘요."}, {"id": "C", "text": "아, 그래요? 몰랐어요. 미안해요."}, {"id": "D", "text": "우유를 샀어요?"}]'::jsonb, '["C"]'::jsonb, 'He is pointing out the milk is his; apologise for taking it.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'basic-life']::text[], 1, TRUE, 'Man: The milk in the fridge is mine. Choices: A. The fridge is big. B. Milk is white. C. Oh, is it? I didn''t know. Sorry. D. Did you buy milk?'),
    ('eps-b2-l-next-12', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 14', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 오늘 오후에 비가 많이 온대요.', NULL, 75, '[{"id": "A", "text": "날씨가 맑아요."}, {"id": "B", "text": "우산을 팔아요."}, {"id": "C", "text": "비가 안 와요."}, {"id": "D", "text": "그럼 우산을 가지고 가야겠어요."}]'::jsonb, '["D"]'::jsonb, 'Rain is forecast, so take an umbrella.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'daily-life']::text[], 1, TRUE, 'Woman: They say it''ll rain heavily this afternoon. Choices: A. The weather is clear. B. I sell umbrellas. C. It isn''t raining. D. Then I''d better take an umbrella.'),
    ('eps-b2-l-next-13', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 15', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 새로 온 직원이에요. 잘 부탁드립니다.', NULL, 75, '[{"id": "A", "text": "반가워요. 모르는 것이 있으면 물어보세요."}, {"id": "B", "text": "새 옷이에요."}, {"id": "C", "text": "직원이 많아요."}, {"id": "D", "text": "잘 먹겠습니다."}]'::jsonb, '["A"]'::jsonb, 'Welcome a new co-worker and offer help.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'workplace-culture']::text[], 1, TRUE, 'Man: I''m the new member of staff. I look forward to working with you. Choices: A. Nice to meet you. Ask if there''s anything you don''t know. B. They''re new clothes. C. There are lots of staff. D. Thank you for the meal.'),
    ('eps-b2-l-next-14', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 16', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 작업할 때는 꼭 안전모를 쓰세요.', NULL, 75, '[{"id": "A", "text": "모자가 예뻐요."}, {"id": "B", "text": "네, 지금 바로 쓸게요."}, {"id": "C", "text": "안전모를 벗을게요."}, {"id": "D", "text": "작업이 끝났어요."}]'::jsonb, '["B"]'::jsonb, 'A safety instruction: put the helmet on.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'industrial-safety']::text[], 1, TRUE, 'Woman: Always wear a safety helmet when you''re working. Choices: A. The hat is pretty. B. OK, I''ll put it on right now. C. I''ll take my helmet off. D. The work is done.'),
    ('eps-b2-l-next-15', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 17', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 손을 다쳤으니까 병원에 가 보세요.', NULL, 75, '[{"id": "A", "text": "손을 씻었어요."}, {"id": "B", "text": "병원이 커요."}, {"id": "C", "text": "네, 지금 다녀오겠습니다."}, {"id": "D", "text": "손이 두 개예요."}]'::jsonb, '["C"]'::jsonb, 'Told to see a doctor, agree to go.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'industrial-safety']::text[], 1, TRUE, 'Man: You''ve hurt your hand, so go and see a doctor. Choices: A. I washed my hands. B. The hospital is big. C. OK, I''ll go now and come back. D. I have two hands.'),
    ('eps-b2-l-next-16', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 18', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 다음 달부터 기숙사비가 조금 올라요.', NULL, 75, '[{"id": "A", "text": "기숙사가 깨끗해요."}, {"id": "B", "text": "다음 달이 좋아요."}, {"id": "C", "text": "이 층으로 올라가요."}, {"id": "D", "text": "얼마나 올라요?"}]'::jsonb, '["D"]'::jsonb, 'News of a rise: ask how much.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'basic-life']::text[], 1, TRUE, 'Woman: The dormitory fee goes up a little from next month. Choices: A. The dormitory is clean. B. Next month is good. C. I''m going up to the second floor. D. By how much?'),
    ('eps-b2-l-next-17', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 19', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 이 물건은 깨지기 쉬우니까 조심하세요.', NULL, 75, '[{"id": "A", "text": "네, 천천히 옮길게요."}, {"id": "B", "text": "쉬운 물건이에요."}, {"id": "C", "text": "물건이 싸요."}, {"id": "D", "text": "던질게요."}]'::jsonb, '["A"]'::jsonb, 'Fragile goods: handle them slowly.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'job-korean']::text[], 1, TRUE, 'Man: This item breaks easily, so be careful. Choices: A. OK, I''ll move it slowly. B. It''s an easy item. C. It''s cheap. D. I''ll throw it.'),
    ('eps-b2-l-next-18', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 20', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 여기는 금연 구역이에요.', NULL, 75, '[{"id": "A", "text": "담배를 사요."}, {"id": "B", "text": "죄송합니다. 밖에 나가서 피울게요."}, {"id": "C", "text": "금요일이에요."}, {"id": "D", "text": "구역이 넓어요."}]'::jsonb, '["B"]'::jsonb, 'Told not to smoke here, apologise and go outside.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'industrial-safety']::text[], 1, TRUE, 'Woman: This is a no-smoking area. Choices: A. I''m buying cigarettes. B. Sorry. I''ll go outside to smoke. C. It''s Friday. D. The area is wide.'),
    ('eps-b2-l-next-19', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 21', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 오늘은 일이 많으니까 점심을 빨리 먹읍시다.', NULL, 75, '[{"id": "A", "text": "점심은 맛있어요."}, {"id": "B", "text": "일이 없어요."}, {"id": "C", "text": "네, 김밥을 사 와서 먹을까요?"}, {"id": "D", "text": "천천히 먹어요."}]'::jsonb, '["C"]'::jsonb, 'A suggestion to eat quickly; suggest something quick.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'workplace-culture']::text[], 1, TRUE, 'Man: We''ve got a lot of work today, so let''s eat lunch quickly. Choices: A. Lunch is tasty. B. There''s no work. C. OK, shall I get some gimbap for us? D. Let''s eat slowly.'),
    ('eps-b2-l-next-20', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 22', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 지난번에 빌린 책 다 읽었어요?', NULL, 75, '[{"id": "A", "text": "책을 샀어요."}, {"id": "B", "text": "도서관이에요."}, {"id": "C", "text": "책이 두꺼워요."}, {"id": "D", "text": "네, 내일 돌려 드릴게요."}]'::jsonb, '["D"]'::jsonb, 'Asked about a borrowed book, offer to return it.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'daily-life']::text[], 1, TRUE, 'Woman: Have you finished the book you borrowed last time? Choices: A. I bought a book. B. It''s a library. C. The book is thick. D. Yes, I''ll give it back tomorrow.'),
    ('eps-b2-l-next-21', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 23', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 전기를 아끼려면 나갈 때 불을 끄세요.', NULL, 75, '[{"id": "A", "text": "네, 나갈 때 꼭 끌게요."}, {"id": "B", "text": "불을 켤게요."}, {"id": "C", "text": "전기가 비싸요."}, {"id": "D", "text": "밖이 어두워요."}]'::jsonb, '["A"]'::jsonb, 'A request to turn lights off: agree.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'basic-life']::text[], 1, TRUE, 'Man: To save electricity, turn off the lights when you leave. Choices: A. OK, I''ll be sure to turn them off when I leave. B. I''ll turn them on. C. Electricity is expensive. D. It''s dark outside.'),
    ('eps-b2-l-next-22', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 24', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 휴대폰을 잃어버렸어요.', NULL, 75, '[{"id": "A", "text": "휴대폰이 비싸요."}, {"id": "B", "text": "마지막으로 어디에서 썼어요?"}, {"id": "C", "text": "새 휴대폰이에요."}, {"id": "D", "text": "휴대폰을 샀어요."}]'::jsonb, '["B"]'::jsonb, 'Help look for it: ask where it was last used.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'daily-life']::text[], 1, TRUE, 'Woman: I''ve lost my mobile phone. Choices: A. Mobiles are expensive. B. Where did you last use it? C. It''s a new mobile. D. I bought a mobile.'),
    ('eps-b2-l-next-23', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 25', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 다음 주에 건강 검진이 있어요.', NULL, 75, '[{"id": "A", "text": "건강해요."}, {"id": "B", "text": "지난주에 아팠어요."}, {"id": "C", "text": "무슨 요일에 해요?"}, {"id": "D", "text": "병원이 멀어요."}]'::jsonb, '["C"]'::jsonb, 'News of a check-up: ask what day.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'public-services']::text[], 1, TRUE, 'Man: There''s a health check next week. Choices: A. I''m healthy. B. I was ill last week. C. What day is it? D. The hospital is far.'),
    ('eps-b2-l-next-24', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 26', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 이 일이 끝나면 저쪽 창고도 정리해 주세요.', NULL, 75, '[{"id": "A", "text": "창고가 커요."}, {"id": "B", "text": "일이 끝났어요."}, {"id": "C", "text": "저쪽이에요."}, {"id": "D", "text": "네, 끝나고 바로 정리할게요."}]'::jsonb, '["D"]'::jsonb, 'A request: agree to do it.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'job-korean']::text[], 1, TRUE, 'Woman: When you''ve finished this, please tidy the storeroom over there too. Choices: A. The storeroom is big. B. The work is done. C. It''s over there. D. OK, I''ll tidy it as soon as I''ve finished.'),
    ('eps-b2-l-next-25', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 27', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 설날에는 공장이 사흘 동안 쉽니다.', NULL, 75, '[{"id": "A", "text": "그럼 그때 친구들하고 여행을 가야겠어요."}, {"id": "B", "text": "설날은 겨울이에요."}, {"id": "C", "text": "사흘 동안 일할게요."}, {"id": "D", "text": "공장이 바빠요."}]'::jsonb, '["A"]'::jsonb, 'Days off are coming: make a plan for them.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'korean-culture']::text[], 1, TRUE, 'Man: The factory closes for three days over New Year. Choices: A. Then I''ll go on a trip with friends. B. New Year is in winter. C. I''ll work for three days. D. The factory is busy.'),
    ('eps-b2-l-next-26', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 28', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 기숙사 근처에 새 마트가 생겼어요.', NULL, 75, '[{"id": "A", "text": "마트에서 일해요."}, {"id": "B", "text": "그래요? 이따가 같이 가 봐요."}, {"id": "C", "text": "기숙사가 멀어요."}, {"id": "D", "text": "새 옷을 샀어요."}]'::jsonb, '["B"]'::jsonb, 'News of a new shop: suggest visiting it.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'basic-life']::text[], 1, TRUE, 'Woman: A new supermarket has opened near the dorm. Choices: A. I work at a supermarket. B. Really? Let''s go and have a look later. C. The dorm is far. D. I bought new clothes.'),
    ('eps-b2-l-next-27', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 29', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 이 기계는 아직 고치는 중이에요.', NULL, 75, '[{"id": "A", "text": "기계를 고쳤어요."}, {"id": "B", "text": "고치는 사람이에요."}, {"id": "C", "text": "그럼 다른 기계를 사용할게요."}, {"id": "D", "text": "기계가 새것이에요."}]'::jsonb, '["C"]'::jsonb, 'The machine can''t be used; use another one.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'tools-machines']::text[], 1, TRUE, 'Man: This machine is still being repaired. Choices: A. I fixed the machine. B. I''m the repairer. C. Then I''ll use another machine. D. The machine is new.'),
    ('eps-b2-l-next-28', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 30', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 오늘이 제 생일이에요.', NULL, 75, '[{"id": "A", "text": "오늘은 금요일이에요."}, {"id": "B", "text": "생일이 언제예요?"}, {"id": "C", "text": "축하해 주세요."}, {"id": "D", "text": "생일 축하해요! 오늘 저녁은 제가 살게요."}]'::jsonb, '["D"]'::jsonb, 'She has just said it is her birthday: congratulate her.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'daily-life']::text[], 1, TRUE, 'Woman: Today''s my birthday. Choices: A. Today is Friday. B. When''s your birthday? C. Please congratulate me. D. Happy birthday! Dinner''s on me tonight.'),
    ('eps-b2-l-next-29', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 31', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 제가 길을 잘 몰라서요.', NULL, 75, '[{"id": "A", "text": "제가 같이 가 드릴게요."}, {"id": "B", "text": "길이 넓어요."}, {"id": "C", "text": "저도 길이에요."}, {"id": "D", "text": "지도를 팔아요."}]'::jsonb, '["A"]'::jsonb, 'He is lost; offer to show him.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'daily-life']::text[], 1, TRUE, 'Man: I don''t really know the way. Choices: A. I''ll go with you. B. The road is wide. C. I''m a road too. D. I sell maps.'),
    ('eps-b2-l-next-30', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 32', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 오늘 처음으로 지게차를 운전해요.', NULL, 75, '[{"id": "A", "text": "지게차가 노래요."}, {"id": "B", "text": "처음이니까 천천히 조심해서 하세요."}, {"id": "C", "text": "차를 샀어요."}, {"id": "D", "text": "빨리 운전하세요."}]'::jsonb, '["B"]'::jsonb, 'A first time on a forklift: advise care.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'industrial-safety']::text[], 1, TRUE, 'Woman: Today I''m driving the forklift for the first time. Choices: A. The forklift is yellow. B. It''s your first time, so go slowly and carefully. C. I bought a car. D. Drive fast.'),
    ('eps-b2-l-next-31', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 33', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 화장실 물이 안 내려가요.', NULL, 75, '[{"id": "A", "text": "물을 마셔요."}, {"id": "B", "text": "화장실이 깨끗해요."}, {"id": "C", "text": "관리실에 전화해서 고쳐 달라고 할게요."}, {"id": "D", "text": "물이 차가워요."}]'::jsonb, '["C"]'::jsonb, 'Something is broken: call someone to fix it.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'basic-life']::text[], 1, TRUE, 'Man: The toilet won''t flush. Choices: A. I''m drinking water. B. The toilet is clean. C. I''ll call the management office and ask them to fix it. D. The water is cold.'),
    ('eps-b2-l-next-32', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 34', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 내일 아침에 비행기 타고 고향에 가요.', NULL, 75, '[{"id": "A", "text": "비행기가 커요."}, {"id": "B", "text": "어제 고향에 갔어요."}, {"id": "C", "text": "아침을 먹어요."}, {"id": "D", "text": "잘 다녀오세요. 가족들에게 안부 전해 주세요."}]'::jsonb, '["D"]'::jsonb, 'Someone is leaving on a trip: wish them well.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'basic-life']::text[], 1, TRUE, 'Woman: I''m flying home tomorrow morning. Choices: A. The plane is big. B. I went home yesterday. C. I''m eating breakfast. D. Have a good trip. Say hello to your family.'),
    ('eps-b2-l-next-33', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 35', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 이 방은 너무 더워요.', NULL, 75, '[{"id": "A", "text": "에어컨을 켤까요?"}, {"id": "B", "text": "방이 커요."}, {"id": "C", "text": "겨울이에요."}, {"id": "D", "text": "난방을 켤게요."}]'::jsonb, '["A"]'::jsonb, 'The room is hot, so offer to cool it. Heating would make it worse.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'basic-life']::text[], 1, TRUE, 'Man: This room is too hot. Choices: A. Shall I turn on the air conditioning? B. The room is big. C. It''s winter. D. I''ll turn on the heating.'),
    ('eps-b2-l-next-34', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 36', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 계약 기간이 다음 달에 끝나요.', NULL, 75, '[{"id": "A", "text": "계약서가 하얘요."}, {"id": "B", "text": "계약을 연장할 거예요?"}, {"id": "C", "text": "지난달에 끝났어요."}, {"id": "D", "text": "다음 달이 좋아요."}]'::jsonb, '["B"]'::jsonb, 'A contract ending: ask about renewing it.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'laws-systems']::text[], 1, TRUE, 'Woman: My contract ends next month. Choices: A. The contract is white. B. Are you going to extend it? C. It ended last month. D. Next month is good.'),
    ('eps-b2-l-next-35', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 37', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 공구는 쓰고 나서 제자리에 놓으세요.', NULL, 75, '[{"id": "A", "text": "공구가 많아요."}, {"id": "B", "text": "제자리에 앉을게요."}, {"id": "C", "text": "네, 다 쓰고 정리하겠습니다."}, {"id": "D", "text": "공구를 샀어요."}]'::jsonb, '["C"]'::jsonb, 'An instruction to put tools away: agree.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'tools-machines']::text[], 1, TRUE, 'Man: Put the tools back in their place after use. Choices: A. There are many tools. B. I''ll sit in my seat. C. OK, I''ll tidy up when I''ve finished. D. I bought tools.'),
    ('eps-b2-l-next-36', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 38', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 버스 카드를 집에 놓고 왔어요.', NULL, 75, '[{"id": "A", "text": "버스가 왔어요."}, {"id": "B", "text": "카드가 예뻐요."}, {"id": "C", "text": "집이 커요."}, {"id": "D", "text": "제가 버스비를 빌려 드릴게요."}]'::jsonb, '["D"]'::jsonb, 'She can''t pay the fare; offer to lend it.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'public-services']::text[], 1, TRUE, 'Woman: I''ve left my bus card at home. Choices: A. The bus has come. B. The card is pretty. C. The house is big. D. I''ll lend you the fare.'),
    ('eps-b2-l-next-37', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 39', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 다음 주부터 한국어 수업이 시작돼요.', NULL, 75, '[{"id": "A", "text": "저도 신청하고 싶어요. 어디에서 해요?"}, {"id": "B", "text": "한국어가 쉬워요."}, {"id": "C", "text": "수업이 끝났어요."}, {"id": "D", "text": "지난주에 시작했어요."}]'::jsonb, '["A"]'::jsonb, 'News of a class: ask to join.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'daily-life']::text[], 1, TRUE, 'Man: Korean classes start next week. Choices: A. I''d like to sign up too. Where is it? B. Korean is easy. C. The class is over. D. It started last week.'),
    ('eps-b2-l-next-38', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 40', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 이 음식 너무 매워요.', NULL, 75, '[{"id": "A", "text": "음식이 차가워요."}, {"id": "B", "text": "물 좀 드릴까요?"}, {"id": "C", "text": "저는 매워요."}, {"id": "D", "text": "음식을 만들어요."}]'::jsonb, '["B"]'::jsonb, 'Too spicy: offer water.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'daily-life']::text[], 1, TRUE, 'Woman: This food is too spicy. Choices: A. The food is cold. B. Shall I get you some water? C. I am spicy. D. I''m making food.'),
    ('eps-b2-l-next-39', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 41', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 작업장에 불이 났어요!', NULL, 75, '[{"id": "A", "text": "불을 켜세요."}, {"id": "B", "text": "작업이 끝났어요."}, {"id": "C", "text": "빨리 밖으로 나가서 일일구에 전화하세요!"}, {"id": "D", "text": "불고기를 먹어요."}]'::jsonb, '["C"]'::jsonb, 'In a fire, get out and call 119, Korea''s fire and ambulance number.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'industrial-safety']::text[], 1, TRUE, 'Man: There''s a fire in the workshop! Choices: A. Turn on the light. B. The work is done. C. Get outside quickly and call 119! D. I''m eating bulgogi.'),
    ('eps-b2-l-next-40', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 42', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 은행이 네 시에 문을 닫아요.', NULL, 75, '[{"id": "A", "text": "은행이 열어요."}, {"id": "B", "text": "네 시에 일어나요."}, {"id": "C", "text": "돈이 많아요."}, {"id": "D", "text": "그럼 지금 빨리 가야겠어요."}]'::jsonb, '["D"]'::jsonb, 'The bank closes soon, so hurry.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'public-services']::text[], 1, TRUE, 'Woman: The bank closes at four. Choices: A. The bank opens. B. I get up at four. C. I have a lot of money. D. Then I''d better go now.'),
    ('eps-b2-l-next-41', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 43', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 오늘 작업은 여기까지 합시다.', NULL, 75, '[{"id": "A", "text": "수고하셨습니다. 내일 뵙겠습니다."}, {"id": "B", "text": "작업을 시작할게요."}, {"id": "C", "text": "여기는 공장이에요."}, {"id": "D", "text": "오늘은 월요일이에요."}]'::jsonb, '["A"]'::jsonb, 'End of the working day: 수고하셨습니다 is the usual reply.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'workplace-culture']::text[], 1, TRUE, 'Man: Let''s stop work here for today. Choices: A. Thanks for your hard work. See you tomorrow. B. I''ll start work. C. This is a factory. D. Today is Monday.'),
    ('eps-b2-l-next-42', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 44', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 이번 달 월급이 조금 늦게 나온대요.', NULL, 75, '[{"id": "A", "text": "월급을 받았어요."}, {"id": "B", "text": "언제쯤 나온대요?"}, {"id": "C", "text": "늦게 일어났어요."}, {"id": "D", "text": "은행이에요."}]'::jsonb, '["B"]'::jsonb, 'Pay will be late: ask when it will come.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'job-korean']::text[], 1, TRUE, 'Woman: They say this month''s pay will be a bit late. Choices: A. I''ve been paid. B. When will it come, did they say? C. I got up late. D. It''s a bank.'),
    ('eps-b2-l-next-43', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 45', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 제 자리에 누가 가방을 놓았어요.', NULL, 75, '[{"id": "A", "text": "가방을 샀어요."}, {"id": "B", "text": "자리가 넓어요."}, {"id": "C", "text": "아, 죄송해요. 제 가방이에요. 치울게요."}, {"id": "D", "text": "가방이 무거워요."}]'::jsonb, '["C"]'::jsonb, 'The owner of the bag apologises and moves it.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'daily-life']::text[], 1, TRUE, 'Man: Someone has put a bag on my seat. Choices: A. I bought a bag. B. The seat is wide. C. Oh, sorry. It''s my bag. I''ll move it. D. The bag is heavy.'),
    ('eps-b2-l-next-44', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 46', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 이 약을 먹으면 졸릴 수 있어요.', NULL, 75, '[{"id": "A", "text": "약이 달아요."}, {"id": "B", "text": "잠을 잘 잤어요."}, {"id": "C", "text": "약국에 가요."}, {"id": "D", "text": "그럼 먹고 나서 운전하지 않을게요."}]'::jsonb, '["D"]'::jsonb, 'A warning about drowsiness: avoid driving.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'public-services']::text[], 1, TRUE, 'Woman: This medicine may make you sleepy. Choices: A. The medicine is sweet. B. I slept well. C. I''m going to the pharmacy. D. Then I won''t drive after taking it.'),
    ('eps-b2-l-next-45', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 47', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 오늘 오후에 사장님이 공장에 오세요.', NULL, 75, '[{"id": "A", "text": "그럼 작업장을 깨끗하게 청소해야겠어요."}, {"id": "B", "text": "사장님이 가요."}, {"id": "C", "text": "오전에 왔어요."}, {"id": "D", "text": "공장이 멀어요."}]'::jsonb, '["A"]'::jsonb, 'A visit is coming: get ready for it.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'workplace-culture']::text[], 1, TRUE, 'Man: The boss is coming to the factory this afternoon. Choices: A. Then we''d better clean the workshop. B. The boss is going. C. I came in the morning. D. The factory is far.'),
    ('eps-b2-l-next-46', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 48', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 우리 팀이 이번 달 생산 목표를 달성했어요.', NULL, 75, '[{"id": "A", "text": "목표가 없어요."}, {"id": "B", "text": "정말요? 모두 수고 많았어요."}, {"id": "C", "text": "다음 달에 해요."}, {"id": "D", "text": "생산이 뭐예요?"}]'::jsonb, '["B"]'::jsonb, 'Good news: congratulate the team.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'job-korean']::text[], 1, TRUE, 'Woman: Our team has hit this month''s production target. Choices: A. There''s no target. B. Really? Well done, everyone. C. We''ll do it next month. D. What''s production?'),
    ('eps-b2-l-next-47', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 49', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '남: 문이 잠겨서 들어갈 수 없어요.', NULL, 75, '[{"id": "A", "text": "문을 잠갔어요."}, {"id": "B", "text": "들어오세요."}, {"id": "C", "text": "관리실에 열쇠가 있으니까 가 보세요."}, {"id": "D", "text": "문이 커요."}]'::jsonb, '["C"]'::jsonb, 'He can''t get in: tell him where the key is.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'basic-life']::text[], 1, TRUE, 'Man: The door''s locked and I can''t get in. Choices: A. I locked the door. B. Come in. C. The management office has a key, so go there. D. The door is big.'),
    ('eps-b2-l-next-48', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-next', 'What Comes Next', '이어지는 말 50', '다음을 듣고 이어지는 말을 고르십시오.', NULL, '여: 이 컵은 일회용이 아니에요.', NULL, 75, '[{"id": "A", "text": "컵을 버릴게요."}, {"id": "B", "text": "컵이 예뻐요."}, {"id": "C", "text": "일회용 컵이에요."}, {"id": "D", "text": "아, 그럼 씻어서 다시 쓸게요."}]'::jsonb, '["D"]'::jsonb, 'A reusable cup should be washed, not thrown away.', 'medium', ARRAY['EPS_TOPIK Listening', 'What Comes Next', 'basic-life']::text[], 1, TRUE, 'Woman: This cup isn''t disposable. Choices: A. I''ll throw the cup away. B. The cup is pretty. C. It''s a disposable cup. D. Oh, then I''ll wash it and use it again.'),
    ('eps-b2-l-dialogue-01', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 3', '여자가 피곤한 이유는 무엇입니까?', NULL, '남: 오늘 왜 이렇게 피곤해 보여요? 여: 어제 밤늦게까지 야근을 해서 잠을 못 잤어요. 남: 그럼 점심시간에 좀 쉬세요.', NULL, 75, '[{"id": "A", "text": "야근을 해서"}, {"id": "B", "text": "감기에 걸려서"}, {"id": "C", "text": "이사를 해서"}, {"id": "D", "text": "운동을 많이 해서"}]'::jsonb, '["A"]'::jsonb, 'She says 야근을 해서 잠을 못 잤어요: she worked late and couldn''t sleep.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'workplace-culture']::text[], 1, TRUE, 'Man: Why do you look so tired today? Woman: I worked overtime until late last night, so I couldn''t sleep. Man: Then take a rest at lunchtime. Question: Why is the woman tired? Choices: A. She worked overtime. B. She has a cold. C. She moved house. D. She exercised a lot.'),
    ('eps-b2-l-dialogue-02', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 4', '남자는 어디에 왔습니까?', NULL, '여: 어서 오세요. 어디가 불편하세요? 남: 어제부터 목이 아프고 기침이 나요. 여: 열도 있는지 한번 재 볼게요.', NULL, 75, '[{"id": "A", "text": "은행"}, {"id": "B", "text": "병원"}, {"id": "C", "text": "식당"}, {"id": "D", "text": "우체국"}]'::jsonb, '["B"]'::jsonb, 'He describes a sore throat and a cough and has his temperature taken: he is at a clinic.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'public-services']::text[], 1, TRUE, 'Woman: Come in. What seems to be the trouble? Man: My throat has been sore since yesterday and I''m coughing. Woman: Let me check whether you have a temperature too. Question: Where has the man come? Choices: A. A bank. B. A clinic. C. A restaurant. D. A post office.'),
    ('eps-b2-l-dialogue-03', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 5', '두 사람은 어디에 있습니까?', NULL, '남: 이 소포를 베트남에 보내고 싶어요. 여: 안에 뭐가 들어 있어요? 남: 옷하고 과자예요. 여: 저울 위에 올려 주세요.', NULL, 75, '[{"id": "A", "text": "시장"}, {"id": "B", "text": "공항"}, {"id": "C", "text": "우체국"}, {"id": "D", "text": "옷 가게"}]'::jsonb, '["C"]'::jsonb, 'Sending a parcel abroad and weighing it happens at a post office.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'public-services']::text[], 1, TRUE, 'Man: I''d like to send this parcel to Vietnam. Woman: What''s inside? Man: Clothes and snacks. Woman: Please put it on the scales. Question: Where are the two people? Choices: A. At a market. B. At an airport. C. At a post office. D. At a clothes shop.'),
    ('eps-b2-l-dialogue-04', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 6', '여자가 내일 오후에 하려는 일은 무엇입니까?', NULL, '여: 반장님, 내일 오후에 반차를 써도 될까요? 남: 무슨 일 있어요? 여: 외국인 등록증을 새로 받으러 출입국 사무소에 가야 해요. 남: 알겠어요. 신청서를 내세요.', NULL, 75, '[{"id": "A", "text": "병원에 간다"}, {"id": "B", "text": "고향에 간다"}, {"id": "C", "text": "야근을 한다"}, {"id": "D", "text": "출입국 사무소에 간다"}]'::jsonb, '["D"]'::jsonb, 'She needs the afternoon off to get a new registration card at the immigration office.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'laws-systems']::text[], 1, TRUE, 'Woman: Team leader, may I take tomorrow afternoon off? Man: Is something up? Woman: I have to go to the immigration office to get a new alien registration card. Man: All right. Hand in a request form. Question: What is the woman going to do tomorrow afternoon? Choices: A. Go to the hospital. B. Go home to her country. C. Work overtime. D. Go to the immigration office.'),
    ('eps-b2-l-dialogue-05', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 7', '남자는 왜 가게에 왔습니까?', NULL, '남: 이 셔츠 좀 큰 걸로 바꿀 수 있어요? 여: 영수증 있으세요? 남: 네, 여기 있어요. 여: 그럼 엘 사이즈로 바꿔 드릴게요.', NULL, 75, '[{"id": "A", "text": "셔츠를 큰 것으로 바꾸려고"}, {"id": "B", "text": "셔츠를 새로 사려고"}, {"id": "C", "text": "영수증을 받으려고"}, {"id": "D", "text": "돈을 돌려받으려고"}]'::jsonb, '["A"]'::jsonb, 'He asks to swap the shirt for a bigger size, not for a refund.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'daily-life']::text[], 1, TRUE, 'Man: Can I change this shirt for a bigger one? Woman: Do you have the receipt? Man: Yes, here it is. Woman: Then I''ll change it for a large. Question: Why has the man come to the shop? Choices: A. To change the shirt for a bigger one. B. To buy a new shirt. C. To get a receipt. D. To get his money back.'),
    ('eps-b2-l-dialogue-06', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 8', '대화의 내용과 같은 것을 고르십시오.', NULL, '여: 기숙사 세탁기가 고장 났어요. 남: 그래요? 관리실에 말했어요? 여: 네, 내일 고쳐 준대요. 남: 그럼 오늘은 제 방 세탁기를 쓰세요.', NULL, 75, '[{"id": "A", "text": "여자는 관리실에 말하지 않았다."}, {"id": "B", "text": "세탁기는 내일 고칠 것이다."}, {"id": "C", "text": "남자의 세탁기도 고장 났다."}, {"id": "D", "text": "세탁기는 오늘 고쳤다."}]'::jsonb, '["B"]'::jsonb, 'The office says it will fix the machine tomorrow (내일 고쳐 준대요).', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'basic-life']::text[], 1, TRUE, 'Woman: The dormitory washing machine is broken. Man: Is it? Did you tell the management office? Woman: Yes, they say they''ll fix it tomorrow. Man: Then use the washing machine in my room today. Question: Which statement matches the conversation? Choices: A. The woman did not tell the office. B. The washing machine will be fixed tomorrow. C. The man''s machine is broken too. D. The machine was fixed today.'),
    ('eps-b2-l-dialogue-07', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 9', '여자에 대한 내용으로 맞는 것을 고르십시오.', NULL, '남: 지게차를 운전할 수 있어요? 여: 네, 고향에서 면허를 땄어요. 남: 한국 면허도 있어요? 여: 아니요, 한국 면허는 아직 없어요.', NULL, 75, '[{"id": "A", "text": "지게차를 운전할 수 없다."}, {"id": "B", "text": "한국에서 면허를 땄다."}, {"id": "C", "text": "한국 지게차 면허가 없다."}, {"id": "D", "text": "면허가 두 개 있다."}]'::jsonb, '["C"]'::jsonb, 'She has a licence from home but no Korean one yet.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'tools-machines']::text[], 1, TRUE, 'Man: Can you drive a forklift? Woman: Yes, I got a licence back home. Man: Do you have a Korean licence too? Woman: No, I don''t have a Korean licence yet. Question: Which is true of the woman? Choices: A. She can''t drive a forklift. B. She got her licence in Korea. C. She has no Korean forklift licence. D. She has two licences.'),
    ('eps-b2-l-dialogue-08', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 10', '두 사람은 언제 등산을 갑니까?', NULL, '여: 이번 주 토요일에 같이 등산 갈래요? 남: 미안해요. 토요일에는 특근이 있어요. 여: 그럼 일요일은 어때요? 남: 일요일은 좋아요.', NULL, 75, '[{"id": "A", "text": "토요일"}, {"id": "B", "text": "금요일"}, {"id": "C", "text": "가지 않는다"}, {"id": "D", "text": "일요일"}]'::jsonb, '["D"]'::jsonb, 'He works on Saturday, so they agree on Sunday.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'daily-life']::text[], 1, TRUE, 'Woman: Would you like to go hiking together this Saturday? Man: Sorry, I have extra shifts on Saturday. Woman: Then how about Sunday? Man: Sunday''s good. Question: When will they go hiking? Choices: A. Saturday. B. Friday. C. They won''t go. D. Sunday.'),
    ('eps-b2-l-dialogue-09', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 11', '기계를 켤 때 처음에 해야 하는 것은 무엇입니까?', NULL, '남: 이 기계는 어떻게 켜요? 여: 먼저 빨간 버튼을 누르고, 초록색 불이 켜지면 시작 버튼을 누르세요. 남: 끌 때는요? 여: 빨간 버튼을 다시 누르면 돼요.', NULL, 75, '[{"id": "A", "text": "빨간 버튼을 누른다"}, {"id": "B", "text": "시작 버튼을 누른다"}, {"id": "C", "text": "초록색 버튼을 누른다"}, {"id": "D", "text": "전원을 뽑는다"}]'::jsonb, '["A"]'::jsonb, '먼저 빨간 버튼을 누르고: the red button comes first.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'tools-machines']::text[], 1, TRUE, 'Man: How do I turn this machine on? Woman: First press the red button, and when the green light comes on, press the start button. Man: And to turn it off? Woman: Just press the red button again. Question: What must you do first to turn the machine on? Choices: A. Press the red button. B. Press the start button. C. Press the green button. D. Unplug it.'),
    ('eps-b2-l-dialogue-10', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 12', '남자가 여자에게 알려 준 것은 무엇입니까?', NULL, '여: 고향에 돈을 보내려면 어떻게 해야 해요? 남: 은행에 가서 해외 송금을 신청하면 돼요. 여: 수수료가 비싸요? 남: 은행마다 달라요. 외국인 근로자 전용 창구에 물어보세요.', NULL, 75, '[{"id": "A", "text": "은행 위치"}, {"id": "B", "text": "돈을 보내는 방법"}, {"id": "C", "text": "월급날"}, {"id": "D", "text": "환율"}]'::jsonb, '["B"]'::jsonb, 'She asks how to send money home and he explains the steps.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'public-services']::text[], 1, TRUE, 'Woman: How do I send money home? Man: Go to a bank and ask for an overseas transfer. Woman: Are the fees expensive? Man: They differ from bank to bank. Ask at the counter for foreign workers. Question: What does the man tell the woman? Choices: A. Where the bank is. B. How to send money. C. When payday is. D. The exchange rate.'),
    ('eps-b2-l-dialogue-11', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 13', '여자는 공휴일에 무엇을 할 겁니까?', NULL, '남: 다음 주 화요일이 공휴일이에요. 여: 그래요? 그럼 회사도 쉬어요? 남: 네, 우리 회사는 쉬어요. 여: 잘됐네요. 친구를 만나러 서울에 가야겠어요.', NULL, 75, '[{"id": "A", "text": "회사에서 일한다"}, {"id": "B", "text": "집에서 쉰다"}, {"id": "C", "text": "서울에서 친구를 만난다"}, {"id": "D", "text": "고향에 간다"}]'::jsonb, '["C"]'::jsonb, 'She says she will go to Seoul to see a friend.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'korean-culture']::text[], 1, TRUE, 'Man: Next Tuesday is a public holiday. Woman: Is it? Does the company close too? Man: Yes, our company is closed. Woman: Great. I''ll go to Seoul to see a friend. Question: What will the woman do on the holiday? Choices: A. Work at the company. B. Rest at home. C. Meet a friend in Seoul. D. Go home to her country.'),
    ('eps-b2-l-dialogue-12', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 14', '남자가 장갑을 끼지 않은 이유는 무엇입니까?', NULL, '여: 작업할 때 왜 장갑을 안 꼈어요? 남: 장갑이 찢어져서요. 여: 창고에 새 장갑이 있으니까 가져가세요. 남: 네, 지금 가져올게요.', NULL, 75, '[{"id": "A", "text": "장갑이 없어서"}, {"id": "B", "text": "날씨가 더워서"}, {"id": "C", "text": "장갑이 커서"}, {"id": "D", "text": "장갑이 찢어져서"}]'::jsonb, '["D"]'::jsonb, '장갑이 찢어져서요: his gloves were torn.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'industrial-safety']::text[], 1, TRUE, 'Woman: Why weren''t you wearing gloves while you worked? Man: They were torn. Woman: There are new gloves in the storeroom, so take some. Man: OK, I''ll go and get them now. Question: Why wasn''t the man wearing gloves? Choices: A. He had no gloves. B. It was hot. C. The gloves were too big. D. His gloves were torn.'),
    ('eps-b2-l-dialogue-13', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 15', '남자는 무엇을 타야 합니까?', NULL, '남: 이 버스가 시청 앞에 서요? 여: 아니요, 이 버스는 안 가요. 길 건너서 백이십 번 버스를 타세요. 남: 감사합니다.', NULL, 75, '[{"id": "A", "text": "길 건너에서 120번 버스"}, {"id": "B", "text": "이 버스"}, {"id": "C", "text": "지하철"}, {"id": "D", "text": "택시"}]'::jsonb, '["A"]'::jsonb, 'She tells him to cross the road and take bus 120.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'public-services']::text[], 1, TRUE, 'Man: Does this bus stop outside City Hall? Woman: No, this bus doesn''t go there. Cross the road and take the number 120 bus. Man: Thank you. Question: What should the man take? Choices: A. The number 120 bus across the road. B. This bus. C. The underground. D. A taxi.'),
    ('eps-b2-l-dialogue-14', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 16', '남자에 대한 내용으로 맞는 것을 고르십시오.', NULL, '여: 무슨 일을 하세요? 남: 자동차 부품 공장에서 일해요. 여: 일이 힘들지 않아요? 남: 처음에는 힘들었는데 지금은 괜찮아요.', NULL, 75, '[{"id": "A", "text": "자동차를 판다."}, {"id": "B", "text": "지금은 일이 괜찮다."}, {"id": "C", "text": "지금도 일이 힘들다."}, {"id": "D", "text": "공장에서 일한 적이 없다."}]'::jsonb, '["B"]'::jsonb, '처음에는 힘들었는데 지금은 괜찮아요: hard at first, fine now.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'job-korean']::text[], 1, TRUE, 'Woman: What do you do? Man: I work in a car parts factory. Woman: Isn''t the work hard? Man: It was hard at first, but it''s fine now. Question: Which is true of the man? Choices: A. He sells cars. B. The work is fine for him now. C. The work is still hard. D. He has never worked in a factory.'),
    ('eps-b2-l-dialogue-15', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 17', '반 상자는 얼마입니까?', NULL, '남: 사과 한 상자에 얼마예요? 여: 삼만 원이에요. 남: 좀 비싸네요. 반 상자도 팔아요? 여: 네, 반 상자는 만 육천 원이에요.', NULL, 75, '[{"id": "A", "text": "15,000원"}, {"id": "B", "text": "30,000원"}, {"id": "C", "text": "16,000원"}, {"id": "D", "text": "6,000원"}]'::jsonb, '["C"]'::jsonb, '만 육천 원 is 16,000 won: 만 (10,000) + 육천 (6,000).', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'numbers-time']::text[], 1, TRUE, 'Man: How much is a box of apples? Woman: Thirty thousand won. Man: That''s a bit expensive. Do you sell half boxes? Woman: Yes, a half box is sixteen thousand won. Question: How much is a half box? Choices: A. 15,000 won. B. 30,000 won. C. 16,000 won. D. 6,000 won.'),
    ('eps-b2-l-dialogue-16', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 18', '통근 버스는 몇 시에 출발합니까?', NULL, '여: 이번 달부터 통근 버스 시간이 바뀌었어요. 남: 몇 시로 바뀌었어요? 여: 아침 일곱 시 사십 분에 기숙사 앞에서 출발해요. 남: 십 분 빨라졌네요.', NULL, 75, '[{"id": "A", "text": "7시 50분"}, {"id": "B", "text": "7시 30분"}, {"id": "C", "text": "8시"}, {"id": "D", "text": "7시 40분"}]'::jsonb, '["D"]'::jsonb, '일곱 시 사십 분 is 7:40, ten minutes earlier than before.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'numbers-time']::text[], 1, TRUE, 'Woman: The shuttle bus times changed this month. Man: To what time? Woman: It leaves from outside the dormitory at seven forty in the morning. Man: So it''s ten minutes earlier. Question: What time does the shuttle bus leave? Choices: A. 7:50. B. 7:30. C. 8:00. D. 7:40.'),
    ('eps-b2-l-dialogue-17', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 19', '여자가 전화를 받지 못한 이유는 무엇입니까?', NULL, '남: 어제 왜 전화를 안 받았어요? 여: 휴대폰 배터리가 다 돼서 꺼졌어요. 남: 무슨 일이 있는 줄 알고 걱정했어요. 여: 미안해요. 충전기를 회사에 두고 왔거든요.', NULL, 75, '[{"id": "A", "text": "배터리가 다 돼서"}, {"id": "B", "text": "휴대폰을 잃어버려서"}, {"id": "C", "text": "일을 하고 있어서"}, {"id": "D", "text": "잠을 자고 있어서"}]'::jsonb, '["A"]'::jsonb, '배터리가 다 돼서 꺼졌어요: the battery died.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'daily-life']::text[], 1, TRUE, 'Man: Why didn''t you answer the phone yesterday? Woman: My mobile battery ran out and it turned off. Man: I was worried something had happened. Woman: Sorry. I''d left my charger at work. Question: Why couldn''t the woman answer the phone? Choices: A. Her battery had run out. B. She had lost her phone. C. She was working. D. She was asleep.'),
    ('eps-b2-l-dialogue-18', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 20', '서류는 언제까지 내야 합니까?', NULL, '여: 이 서류는 어디에 내야 해요? 남: 일 층 인사과에 내면 돼요. 여: 오늘까지 내야 해요? 남: 아니요, 금요일까지 내면 돼요.', NULL, 75, '[{"id": "A", "text": "오늘까지"}, {"id": "B", "text": "금요일까지"}, {"id": "C", "text": "내일까지"}, {"id": "D", "text": "다음 주까지"}]'::jsonb, '["B"]'::jsonb, '금요일까지 내면 돼요: by Friday.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'laws-systems']::text[], 1, TRUE, 'Woman: Where do I hand in this form? Man: At the personnel office on the first floor. Woman: Does it have to be in by today? Man: No, Friday is fine. Question: By when must the form be handed in? Choices: A. By today. B. By Friday. C. By tomorrow. D. By next week.'),
    ('eps-b2-l-dialogue-19', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 21', '여자는 주말에 무엇을 했습니까?', NULL, '남: 주말에 뭐 했어요? 여: 친구들하고 한강 공원에서 자전거를 탔어요. 남: 재미있었겠네요. 여: 네, 날씨도 좋아서 정말 즐거웠어요.', NULL, 75, '[{"id": "A", "text": "집에서 쉬었다"}, {"id": "B", "text": "회사에서 일했다"}, {"id": "C", "text": "공원에서 자전거를 탔다"}, {"id": "D", "text": "수영을 했다"}]'::jsonb, '["C"]'::jsonb, '한강 공원에서 자전거를 탔어요: she cycled in the park.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'daily-life']::text[], 1, TRUE, 'Man: What did you do at the weekend? Woman: I rode bikes with friends in Hangang Park. Man: That must have been fun. Woman: Yes, the weather was nice too, so it was really enjoyable. Question: What did the woman do at the weekend? Choices: A. Rested at home. B. Worked at the company. C. Rode a bike in the park. D. Went swimming.'),
    ('eps-b2-l-dialogue-20', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 22', '회식은 어디에서 합니까?', NULL, '여: 오늘 회식은 어디에서 해요? 남: 회사 앞 삼겹살집에서 해요. 여: 몇 시에 시작해요? 남: 일 끝나고 바로, 여섯 시 반쯤이요.', NULL, 75, '[{"id": "A", "text": "회사 식당"}, {"id": "B", "text": "기숙사"}, {"id": "C", "text": "사장님 집"}, {"id": "D", "text": "회사 앞 식당"}]'::jsonb, '["D"]'::jsonb, '회사 앞 삼겹살집: a restaurant in front of the company.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'workplace-culture']::text[], 1, TRUE, 'Woman: Where''s the staff dinner today? Man: At the pork belly restaurant in front of the company. Woman: What time does it start? Man: Straight after work, around half past six. Question: Where is the staff dinner? Choices: A. In the company canteen. B. In the dormitory. C. At the boss''s house. D. At a restaurant in front of the company.'),
    ('eps-b2-l-dialogue-21', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 23', '여자는 어떻게 다쳤습니까?', NULL, '남: 손가락을 왜 그래요? 여: 상자를 옮기다가 문에 끼었어요. 남: 많이 아프겠네요. 병원에 가 봤어요? 여: 아직이요. 이따가 갈 거예요.', NULL, 75, '[{"id": "A", "text": "문에 손가락이 끼었다"}, {"id": "B", "text": "칼에 베였다"}, {"id": "C", "text": "넘어졌다"}, {"id": "D", "text": "상자가 발에 떨어졌다"}]'::jsonb, '["A"]'::jsonb, '상자를 옮기다가 문에 끼었어요: she caught it in a door.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'industrial-safety']::text[], 1, TRUE, 'Man: What happened to your finger? Woman: I caught it in a door while I was moving boxes. Man: That must hurt a lot. Have you been to the hospital? Woman: Not yet. I''ll go later. Question: How did the woman get hurt? Choices: A. She caught her finger in a door. B. She cut it on a knife. C. She fell over. D. A box fell on her foot.'),
    ('eps-b2-l-dialogue-22', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 24', '대화의 내용과 같은 것을 고르십시오.', NULL, '여: 다음 달에 기숙사에서 이사 나가요. 남: 어디로 가요? 여: 회사 근처 원룸으로 가요. 남: 월세는 얼마예요? 여: 삼십만 원이에요.', NULL, 75, '[{"id": "A", "text": "여자는 기숙사로 이사 온다."}, {"id": "B", "text": "여자는 원룸으로 이사한다."}, {"id": "C", "text": "월세는 삼만 원이다."}, {"id": "D", "text": "원룸은 회사에서 멀다."}]'::jsonb, '["B"]'::jsonb, 'She is moving to a studio flat near work; the rent is 300,000 won.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'basic-life']::text[], 1, TRUE, 'Woman: I''m moving out of the dormitory next month. Man: Where to? Woman: To a studio flat near the company. Man: How much is the rent? Woman: Three hundred thousand won. Question: Which statement matches the conversation? Choices: A. The woman is moving into the dorm. B. The woman is moving into a studio flat. C. The rent is 30,000 won. D. The flat is far from work.'),
    ('eps-b2-l-dialogue-23', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 25', '약은 언제 먹습니까?', NULL, '남: 이 약은 하루에 몇 번 먹어요? 여: 하루에 두 번, 아침하고 저녁 식사 후에 드세요. 남: 술을 마셔도 돼요? 여: 아니요, 약을 드시는 동안에는 안 돼요.', NULL, 75, '[{"id": "A", "text": "하루에 세 번"}, {"id": "B", "text": "자기 전에"}, {"id": "C", "text": "아침과 저녁 식사 후"}, {"id": "D", "text": "식사 전에"}]'::jsonb, '["C"]'::jsonb, '하루에 두 번, 아침하고 저녁 식사 후에: twice, after breakfast and dinner.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'public-services']::text[], 1, TRUE, 'Man: How many times a day do I take this medicine? Woman: Twice a day, after breakfast and dinner. Man: Can I drink alcohol? Woman: No, not while you''re taking the medicine. Question: When should the medicine be taken? Choices: A. Three times a day. B. Before bed. C. After breakfast and dinner. D. Before meals.'),
    ('eps-b2-l-dialogue-24', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 26', '여자가 이제 할 일은 무엇입니까?', NULL, '여: 반장님, 이 부품 불량인 것 같아요. 남: 어디가 문제예요? 여: 여기 금이 가 있어요. 남: 그럼 따로 빼 두고, 몇 개인지 세어서 알려 주세요.', NULL, 75, '[{"id": "A", "text": "부품을 고친다"}, {"id": "B", "text": "새 부품을 산다"}, {"id": "C", "text": "기계를 끈다"}, {"id": "D", "text": "불량 부품을 빼고 개수를 센다"}]'::jsonb, '["D"]'::jsonb, 'He tells her to set the faulty parts aside and count them.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'job-korean']::text[], 1, TRUE, 'Woman: Team leader, I think this part is faulty. Man: What''s the problem? Woman: There''s a crack here. Man: Then set it aside, count how many there are and let me know. Question: What will the woman do now? Choices: A. Repair the part. B. Buy new parts. C. Turn off the machine. D. Set aside the faulty parts and count them.'),
    ('eps-b2-l-dialogue-25', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 27', '화장실은 어디에 있습니까?', NULL, '남: 실례합니다. 화장실이 어디에 있어요? 여: 이 복도 끝에서 오른쪽으로 가세요. 남: 엘리베이터 옆이에요? 여: 네, 엘리베이터 바로 옆이에요.', NULL, 75, '[{"id": "A", "text": "복도 끝 오른쪽, 엘리베이터 옆"}, {"id": "B", "text": "복도 끝 왼쪽"}, {"id": "C", "text": "계단 아래"}, {"id": "D", "text": "이 층 사무실 안"}]'::jsonb, '["A"]'::jsonb, '복도 끝에서 오른쪽 … 엘리베이터 바로 옆: end of the corridor, right, beside the lift.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'basic-life']::text[], 1, TRUE, 'Man: Excuse me. Where is the toilet? Woman: Go to the end of this corridor and turn right. Man: Is it next to the lift? Woman: Yes, right next to the lift. Question: Where is the toilet? Choices: A. At the end of the corridor on the right, next to the lift. B. At the end of the corridor on the left. C. Under the stairs. D. Inside the office on the second floor.'),
    ('eps-b2-l-dialogue-26', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 28', '남자가 고향에 가지 않는 이유는 무엇입니까?', NULL, '여: 이번 휴가 때 고향에 가요? 남: 아니요, 비행기표가 너무 비싸서 못 가요. 여: 그럼 뭐 할 거예요? 남: 부산에 사는 친구 집에 놀러 가려고요.', NULL, 75, '[{"id": "A", "text": "휴가가 짧아서"}, {"id": "B", "text": "비행기표가 비싸서"}, {"id": "C", "text": "일이 많아서"}, {"id": "D", "text": "친구가 한국에 와서"}]'::jsonb, '["B"]'::jsonb, '비행기표가 너무 비싸서 못 가요: the tickets cost too much.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'basic-life']::text[], 1, TRUE, 'Woman: Are you going home for this holiday? Man: No, the plane tickets are too expensive, so I can''t. Woman: Then what will you do? Man: I''m going to visit a friend who lives in Busan. Question: Why isn''t the man going home? Choices: A. The holiday is too short. B. Plane tickets are too expensive. C. He has too much work. D. A friend is coming to Korea.'),
    ('eps-b2-l-dialogue-27', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 29', '이 옷은 어떻게 빨아야 합니까?', NULL, '남: 이 옷을 세탁기에 빨아도 돼요? 여: 아니요, 이건 손으로 빨아야 해요. 남: 뜨거운 물로요? 여: 아니요, 찬물로 빠세요.', NULL, 75, '[{"id": "A", "text": "세탁기에 뜨거운 물로"}, {"id": "B", "text": "손으로 뜨거운 물에"}, {"id": "C", "text": "찬물에 손으로"}, {"id": "D", "text": "세탁소에 맡긴다"}]'::jsonb, '["C"]'::jsonb, '손으로 빨아야 해요 … 찬물로 빠세요: by hand, in cold water.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'basic-life']::text[], 1, TRUE, 'Man: Can I wash this in the washing machine? Woman: No, this has to be washed by hand. Man: In hot water? Woman: No, wash it in cold water. Question: How should this item be washed? Choices: A. In the machine with hot water. B. By hand in hot water. C. By hand in cold water. D. Take it to the dry cleaner.'),
    ('eps-b2-l-dialogue-28', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 30', '두 사람은 어디에서 만납니까?', NULL, '여: 오늘 작업 끝나고 같이 한국어 공부할래요? 남: 좋아요. 어디에서 해요? 여: 기숙사 휴게실에서 해요. 남: 그럼 일곱 시에 휴게실에서 만나요.', NULL, 75, '[{"id": "A", "text": "회사 식당"}, {"id": "B", "text": "도서관"}, {"id": "C", "text": "한국어 학원"}, {"id": "D", "text": "기숙사 휴게실"}]'::jsonb, '["D"]'::jsonb, '기숙사 휴게실에서 … 휴게실에서 만나요: the dorm lounge.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'daily-life']::text[], 1, TRUE, 'Woman: Shall we study Korean together after work today? Man: Sure. Where? Woman: In the dormitory lounge. Man: Then let''s meet in the lounge at seven. Question: Where will the two of them meet? Choices: A. In the company canteen. B. At the library. C. At a Korean school. D. In the dormitory lounge.'),
    ('eps-b2-l-dialogue-29', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 31', '여자는 점심 후에 무엇을 할 겁니까?', NULL, '남: 이번 달 월급 명세서 받았어요? 여: 네, 그런데 야근 수당이 빠진 것 같아요. 남: 그럼 경리과에 가서 물어보세요. 여: 네, 점심 먹고 가 볼게요.', NULL, 75, '[{"id": "A", "text": "경리과에 가서 수당을 물어본다"}, {"id": "B", "text": "은행에 간다"}, {"id": "C", "text": "야근을 한다"}, {"id": "D", "text": "명세서를 버린다"}]'::jsonb, '["A"]'::jsonb, 'Overtime pay is missing, so she will ask the accounts office.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'job-korean']::text[], 1, TRUE, 'Man: Did you get this month''s payslip? Woman: Yes, but I think the overtime pay is missing. Man: Then go and ask the accounts office. Woman: OK, I''ll go after lunch. Question: What will the woman do after lunch? Choices: A. Ask the accounts office about the overtime pay. B. Go to the bank. C. Work overtime. D. Throw away the payslip.'),
    ('eps-b2-l-dialogue-30', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 32', '여자는 몇 정거장을 가야 합니까?', NULL, '여: 여기에서 시청까지 어떻게 가요? 남: 지하철 이 호선을 타고 시청역에서 내리세요. 여: 몇 정거장 가야 해요? 남: 다섯 정거장이에요.', NULL, 75, '[{"id": "A", "text": "두 정거장"}, {"id": "B", "text": "다섯 정거장"}, {"id": "C", "text": "세 정거장"}, {"id": "D", "text": "열 정거장"}]'::jsonb, '["B"]'::jsonb, '다섯 정거장이에요: five stops. 이 호선 is the line number.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'public-services']::text[], 1, TRUE, 'Woman: How do I get to City Hall from here? Man: Take Line 2 and get off at City Hall station. Woman: How many stops is it? Man: Five stops. Question: How many stops must the woman travel? Choices: A. Two stops. B. Five stops. C. Three stops. D. Ten stops.'),
    ('eps-b2-l-dialogue-31', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 33', '여자는 이제 무엇을 할 겁니까?', NULL, '남: 작업장 바닥에 기름이 있어요. 여: 위험하니까 빨리 닦아야 해요. 남: 걸레가 어디 있어요? 여: 청소 도구함에 있어요. 제가 가져올게요.', NULL, 75, '[{"id": "A", "text": "기름을 산다"}, {"id": "B", "text": "기계를 고친다"}, {"id": "C", "text": "걸레를 가져온다"}, {"id": "D", "text": "반장님에게 전화한다"}]'::jsonb, '["C"]'::jsonb, '제가 가져올게요: she will fetch the cloth.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'industrial-safety']::text[], 1, TRUE, 'Man: There''s oil on the workshop floor. Woman: It''s dangerous, so we need to wipe it up quickly. Man: Where are the cloths? Woman: In the cleaning cupboard. I''ll fetch one. Question: What will the woman do now? Choices: A. Buy oil. B. Repair the machine. C. Fetch a cloth. D. Phone the team leader.'),
    ('eps-b2-l-dialogue-32', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 34', '남자는 언제 축구를 합니까?', NULL, '여: 무슨 운동을 좋아해요? 남: 저는 축구를 좋아해요. 주말마다 공원에서 해요. 여: 저도 같이 해도 돼요? 남: 그럼요. 이번 주 일요일 아침에 오세요.', NULL, 75, '[{"id": "A", "text": "매일 저녁"}, {"id": "B", "text": "퇴근 후"}, {"id": "C", "text": "한 달에 한 번"}, {"id": "D", "text": "주말마다"}]'::jsonb, '["D"]'::jsonb, '주말마다 공원에서 해요: every weekend.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'daily-life']::text[], 1, TRUE, 'Woman: What sport do you like? Man: I like football. I play in the park every weekend. Woman: Can I join in? Man: Of course. Come on Sunday morning this week. Question: When does the man play football? Choices: A. Every evening. B. After work. C. Once a month. D. Every weekend.'),
    ('eps-b2-l-dialogue-33', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 35', '한 달 월세는 얼마입니까?', NULL, '남: 이 방은 한 달에 얼마예요? 여: 보증금 백만 원에 월세 이십오만 원이에요. 남: 관리비도 있어요? 여: 네, 관리비는 한 달에 오만 원이에요.', NULL, 75, '[{"id": "A", "text": "250,000원"}, {"id": "B", "text": "1,000,000원"}, {"id": "C", "text": "50,000원"}, {"id": "D", "text": "25,000원"}]'::jsonb, '["A"]'::jsonb, '월세 이십오만 원: 250,000 won. 백만 원 is the deposit.', 'hard', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'numbers-time']::text[], 1, TRUE, 'Man: How much is this room a month? Woman: A deposit of one million won and rent of 250,000 won. Man: Is there a maintenance fee too? Woman: Yes, it''s 50,000 won a month. Question: How much is the monthly rent? Choices: A. 250,000 won. B. 1,000,000 won. C. 50,000 won. D. 25,000 won.'),
    ('eps-b2-l-dialogue-34', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 36', '대화의 내용과 같은 것을 고르십시오.', NULL, '여: 내일 건강 검진이 있어요. 남: 아침을 먹으면 안 돼요? 여: 네, 오늘 밤 아홉 시부터 아무것도 먹지 마세요. 물은 조금 마셔도 돼요.', NULL, 75, '[{"id": "A", "text": "아침을 먹어도 된다."}, {"id": "B", "text": "오늘 밤 아홉 시부터 먹으면 안 된다."}, {"id": "C", "text": "물을 마시면 안 된다."}, {"id": "D", "text": "건강 검진은 오늘이다."}]'::jsonb, '["B"]'::jsonb, '아홉 시부터 아무것도 먹지 마세요; a little water is fine.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'public-services']::text[], 1, TRUE, 'Woman: There''s a health check tomorrow. Man: Can''t I eat breakfast? Woman: That''s right. Don''t eat anything from nine tonight. You can drink a little water. Question: Which statement matches the conversation? Choices: A. Breakfast is allowed. B. No food from nine tonight. C. No water is allowed. D. The check is today.'),
    ('eps-b2-l-dialogue-35', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 37', '여자는 오늘 몇 시에 퇴근합니까?', NULL, '남: 오늘 몇 시에 퇴근해요? 여: 원래 여섯 시인데 오늘은 물건이 많이 들어와서 여덟 시까지 일해야 해요. 남: 힘들겠네요.', NULL, 75, '[{"id": "A", "text": "여섯 시"}, {"id": "B", "text": "일곱 시"}, {"id": "C", "text": "여덟 시"}, {"id": "D", "text": "아홉 시"}]'::jsonb, '["C"]'::jsonb, '원래 여섯 시인데 … 여덟 시까지: usually six, but eight today.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'workplace-culture']::text[], 1, TRUE, 'Man: What time are you finishing today? Woman: Usually six, but a lot of goods have come in today, so I have to work until eight. Man: That''ll be tiring. Question: What time is the woman finishing today? Choices: A. Six o''clock. B. Seven o''clock. C. Eight o''clock. D. Nine o''clock.'),
    ('eps-b2-l-dialogue-36', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 38', '두 사람은 어디에서 일합니까?', NULL, '여: 비닐하우스 안이 너무 더워요. 남: 창문을 열고 환풍기를 켜세요. 여: 물도 줘야 해요? 남: 네, 오후 다섯 시쯤에 주세요.', NULL, 75, '[{"id": "A", "text": "식당"}, {"id": "B", "text": "공사장"}, {"id": "C", "text": "배"}, {"id": "D", "text": "농장"}]'::jsonb, '["D"]'::jsonb, 'A greenhouse (비닐하우스) and watering plants mean farm work.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'job-korean']::text[], 1, TRUE, 'Woman: It''s too hot inside the greenhouse. Man: Open the windows and turn on the fan. Woman: Should I water the plants too? Man: Yes, do it around five in the afternoon. Question: Where do the two people work? Choices: A. In a restaurant. B. On a building site. C. On a boat. D. On a farm.'),
    ('eps-b2-l-dialogue-37', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 39', '남자가 그물을 정리한 후에 할 일은 무엇입니까?', NULL, '남: 그물을 정리하고 나서 뭐 해요? 여: 잡은 생선을 상자에 담아야 해요. 남: 얼음도 넣어요? 여: 네, 생선 위에 얼음을 많이 넣으세요.', NULL, 75, '[{"id": "A", "text": "생선을 상자에 담는다"}, {"id": "B", "text": "생선을 판다"}, {"id": "C", "text": "그물을 산다"}, {"id": "D", "text": "얼음을 만든다"}]'::jsonb, '["A"]'::jsonb, '잡은 생선을 상자에 담아야 해요: pack the catch into boxes, with ice.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'job-korean']::text[], 1, TRUE, 'Man: What do I do after sorting the nets? Woman: We have to pack the fish we caught into boxes. Man: Do we add ice too? Woman: Yes, put lots of ice on top of the fish. Question: What will the man do after sorting the nets? Choices: A. Pack the fish into boxes. B. Sell the fish. C. Buy nets. D. Make ice.'),
    ('eps-b2-l-dialogue-38', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 40', '여자는 시멘트를 어떻게 옮길 겁니까?', NULL, '여: 시멘트를 몇 포대 더 가져올까요? 남: 열 포대 더 가져오세요. 여: 혼자서 옮기기 무거운데요. 남: 그럼 수레를 쓰세요.', NULL, 75, '[{"id": "A", "text": "혼자 들고 옮긴다"}, {"id": "B", "text": "수레로 옮긴다"}, {"id": "C", "text": "트럭으로 옮긴다"}, {"id": "D", "text": "옮기지 않는다"}]'::jsonb, '["B"]'::jsonb, '수레를 쓰세요: use the cart.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'job-korean']::text[], 1, TRUE, 'Woman: How many more bags of cement shall I bring? Man: Bring ten more. Woman: They''re heavy to carry on my own. Man: Then use the cart. Question: How will the woman move the cement? Choices: A. Carry it alone. B. With a cart. C. By lorry. D. She won''t move it.'),
    ('eps-b2-l-dialogue-39', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 41', '돼지에게 밥은 하루에 몇 번 줍니까?', NULL, '남: 이 돼지들은 하루에 몇 번 밥을 줘요? 여: 아침하고 저녁, 두 번 줘요. 남: 물은요? 여: 물은 항상 가득 채워 두세요.', NULL, 75, '[{"id": "A", "text": "한 번"}, {"id": "B", "text": "세 번"}, {"id": "C", "text": "두 번"}, {"id": "D", "text": "항상"}]'::jsonb, '["C"]'::jsonb, '아침하고 저녁, 두 번: twice a day. It is the water that is always kept full.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'job-korean']::text[], 1, TRUE, 'Man: How many times a day do these pigs get fed? Woman: Twice, morning and evening. Man: And water? Woman: Always keep the water full. Question: How many times a day are the pigs fed? Choices: A. Once. B. Three times. C. Twice. D. All the time.'),
    ('eps-b2-l-dialogue-40', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 42', '기계 사용 교육은 누가 합니까?', NULL, '여: 다음 주부터 새로운 기계가 들어와요. 남: 사용법은 누가 가르쳐 줘요? 여: 기계 회사 직원이 와서 교육을 해 줄 거예요. 남: 언제요? 여: 월요일 오전에요.', NULL, 75, '[{"id": "A", "text": "반장님"}, {"id": "B", "text": "사장님"}, {"id": "C", "text": "여자"}, {"id": "D", "text": "기계 회사 직원"}]'::jsonb, '["D"]'::jsonb, '기계 회사 직원이 와서 교육을 해 줄 거예요.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'tools-machines']::text[], 1, TRUE, 'Woman: A new machine arrives next week. Man: Who will teach us how to use it? Woman: Someone from the machine company will come and train us. Man: When? Woman: Monday morning. Question: Who will give the training on the machine? Choices: A. The team leader. B. The boss. C. The woman. D. Staff from the machine company.'),
    ('eps-b2-l-dialogue-41', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 43', '두 사람은 어디까지 같이 갑니까?', NULL, '남: 우산 있어요? 여: 아니요, 안 가져왔어요. 남: 비가 많이 오는데 같이 써요. 여: 고마워요. 버스 정류장까지만 같이 가요.', NULL, 75, '[{"id": "A", "text": "버스 정류장"}, {"id": "B", "text": "집"}, {"id": "C", "text": "회사"}, {"id": "D", "text": "지하철역"}]'::jsonb, '["A"]'::jsonb, '버스 정류장까지만 같이 가요: as far as the bus stop.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'daily-life']::text[], 1, TRUE, 'Man: Have you got an umbrella? Woman: No, I didn''t bring one. Man: It''s raining hard, so let''s share. Woman: Thanks. Let''s go together as far as the bus stop. Question: How far will they go together? Choices: A. To the bus stop. B. Home. C. To the company. D. To the underground station.'),
    ('eps-b2-l-dialogue-42', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 44', '여자가 고향에 가려는 이유는 무엇입니까?', NULL, '여: 사장님, 이번 달에 고향에 다녀와도 될까요? 어머니가 편찮으세요. 남: 많이 아프세요? 여: 네, 수술을 하셔야 해요. 남: 알겠어요. 일주일 휴가를 쓰세요.', NULL, 75, '[{"id": "A", "text": "결혼을 해서"}, {"id": "B", "text": "어머니가 아프셔서"}, {"id": "C", "text": "휴가가 남아서"}, {"id": "D", "text": "비자가 끝나서"}]'::jsonb, '["B"]'::jsonb, '어머니가 편찮으세요: her mother is ill and needs an operation.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'workplace-culture']::text[], 1, TRUE, 'Woman: Boss, may I go home this month? My mother is ill. Man: Is she very ill? Woman: Yes, she has to have an operation. Man: All right. Take a week''s leave. Question: Why does the woman want to go home? Choices: A. She is getting married. B. Her mother is ill. C. She has leave left. D. Her visa is ending.'),
    ('eps-b2-l-dialogue-43', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 45', '남자가 가져가야 하는 것은 무엇입니까?', NULL, '남: 외국인 등록증을 잃어버렸어요. 여: 그럼 출입국 사무소에 가서 다시 신청해야 해요. 남: 뭘 가져가야 해요? 여: 여권하고 사진 한 장을 가져가세요.', NULL, 75, '[{"id": "A", "text": "통장과 도장"}, {"id": "B", "text": "근로계약서"}, {"id": "C", "text": "여권과 사진 한 장"}, {"id": "D", "text": "휴대폰"}]'::jsonb, '["C"]'::jsonb, '여권하고 사진 한 장: a passport and a photo.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'laws-systems']::text[], 1, TRUE, 'Man: I''ve lost my alien registration card. Woman: Then you have to go to the immigration office and apply again. Man: What should I take? Woman: Take your passport and one photo. Question: What must the man take? Choices: A. His bankbook and seal. B. His employment contract. C. His passport and one photo. D. His mobile.'),
    ('eps-b2-l-dialogue-44', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 46', '두 사람은 다음 주말에 무엇을 합니까?', NULL, '여: 이 김치 직접 만들었어요? 남: 네, 회사 아주머니께 배웠어요. 여: 정말 맛있어요. 저도 배우고 싶어요. 남: 그럼 다음 주말에 같이 만들어요.', NULL, 75, '[{"id": "A", "text": "김치를 산다"}, {"id": "B", "text": "식당에 간다"}, {"id": "C", "text": "회사에서 일한다"}, {"id": "D", "text": "같이 김치를 만든다"}]'::jsonb, '["D"]'::jsonb, '다음 주말에 같이 만들어요: they will make kimchi together.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'korean-culture']::text[], 1, TRUE, 'Woman: Did you make this kimchi yourself? Man: Yes, a lady at the company taught me. Woman: It''s really tasty. I''d like to learn too. Man: Then let''s make some together next weekend. Question: What will they do next weekend? Choices: A. Buy kimchi. B. Go to a restaurant. C. Work at the company. D. Make kimchi together.'),
    ('eps-b2-l-dialogue-45', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 47', '두 사람은 어떻게 올라갑니까?', NULL, '남: 엘리베이터가 고장 났어요. 여: 그럼 계단으로 올라가야겠네요. 남: 사무실이 칠 층인데 괜찮아요? 여: 운동한다고 생각하죠, 뭐.', NULL, 75, '[{"id": "A", "text": "계단으로"}, {"id": "B", "text": "엘리베이터로"}, {"id": "C", "text": "에스컬레이터로"}, {"id": "D", "text": "올라가지 않는다"}]'::jsonb, '["A"]'::jsonb, '엘리베이터가 고장 났어요, so 계단으로 올라가야겠네요.', 'easy', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'basic-life']::text[], 1, TRUE, 'Man: The lift is broken. Woman: Then we''ll have to take the stairs. Man: The office is on the seventh floor. Is that OK? Woman: Let''s think of it as exercise. Question: How will they go up? Choices: A. By the stairs. B. By lift. C. By escalator. D. They won''t go up.'),
    ('eps-b2-l-dialogue-46', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 48', '대화의 내용과 같은 것을 고르십시오.', NULL, '여: 오늘 왜 이렇게 일찍 왔어요? 남: 출근 버스를 놓칠까 봐 일찍 나왔어요. 여: 버스 시간이 바뀐 거 몰랐어요? 남: 몰랐어요. 언제 바뀌었어요? 여: 어제부터요.', NULL, 75, '[{"id": "A", "text": "남자는 오늘 늦게 왔다."}, {"id": "B", "text": "남자는 버스 시간이 바뀐 것을 몰랐다."}, {"id": "C", "text": "버스 시간은 내일 바뀐다."}, {"id": "D", "text": "여자는 버스를 놓쳤다."}]'::jsonb, '["B"]'::jsonb, '몰랐어요: he didn''t know. The change began yesterday.', 'hard', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'workplace-culture']::text[], 1, TRUE, 'Woman: Why are you so early today? Man: I left early in case I missed the work bus. Woman: Didn''t you know the bus times changed? Man: No. When did they change? Woman: From yesterday. Question: Which statement matches the conversation? Choices: A. He came late today. B. He didn''t know the bus times had changed. C. The times change tomorrow. D. She missed the bus.'),
    ('eps-b2-l-dialogue-47', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 49', '여자는 남자에게 무엇을 하라고 했습니까?', NULL, '남: 휴대폰 요금이 너무 많이 나왔어요. 여: 해외 전화를 많이 했어요? 남: 네, 고향에 자주 전화했어요. 여: 그럼 인터넷 전화를 써 보세요. 훨씬 싸요.', NULL, 75, '[{"id": "A", "text": "전화를 하지 말라고"}, {"id": "B", "text": "휴대폰을 바꾸라고"}, {"id": "C", "text": "인터넷 전화를 쓰라고"}, {"id": "D", "text": "고향에 가라고"}]'::jsonb, '["C"]'::jsonb, '인터넷 전화를 써 보세요: try internet calls, which are cheaper.', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'daily-life']::text[], 1, TRUE, 'Man: My phone bill is far too high. Woman: Did you make a lot of international calls? Man: Yes, I called home often. Woman: Then try internet calls. They''re much cheaper. Question: What does the woman tell the man to do? Choices: A. Stop calling. B. Get a new phone. C. Use internet calls. D. Go home.'),
    ('eps-b2-l-dialogue-48', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'listening', 'eps-l-dialogue', 'Dialogue Comprehension', '대화 듣기 50', '새로 온 사람은 무슨 일을 합니까?', NULL, '여: 저 사람은 누구예요? 남: 이번에 새로 온 안전 관리자예요. 여: 무슨 일을 해요? 남: 작업장이 안전한지 매일 점검해요.', NULL, 75, '[{"id": "A", "text": "기계를 판다"}, {"id": "B", "text": "월급을 계산한다"}, {"id": "C", "text": "식당에서 요리한다"}, {"id": "D", "text": "작업장 안전을 점검한다"}]'::jsonb, '["D"]'::jsonb, '안전 관리자 checks the workplace is safe every day (매일 점검해요).', 'medium', ARRAY['EPS_TOPIK Listening', 'Dialogue Comprehension', 'industrial-safety']::text[], 1, TRUE, 'Woman: Who''s that? Man: He''s the new safety manager. Woman: What does he do? Man: He checks every day that the workplace is safe. Question: What does the new person do? Choices: A. Sells machines. B. Works out pay. C. Cooks in the canteen. D. Checks that the workplace is safe.'),
    ('eps-b2-r-blank-01', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-blank', 'Fill in the Blank', '빈칸 채우기 3', '빈칸에 들어갈 가장 알맞은 것을 고르십시오.', '배가 고파서 식당에서 밥을 (          ).', NULL, NULL, 75, '[{"id": "A", "text": "먹었어요"}, {"id": "B", "text": "마셨어요"}, {"id": "C", "text": "입었어요"}, {"id": "D", "text": "씻었어요"}]'::jsonb, '["A"]'::jsonb, 'You eat (먹다) rice; 마시다 is for drinks.', 'easy', ARRAY['EPS_TOPIK Reading', 'Fill in the Blank', 'daily-life']::text[], 1, TRUE, 'Text: I was hungry, so I ____ at a restaurant. Question: Choose the best answer for the blank. Choices: A. ate. B. drank. C. wore. D. washed.'),
    ('eps-b2-r-blank-02', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-blank', 'Fill in the Blank', '빈칸 채우기 4', '빈칸에 들어갈 가장 알맞은 것을 고르십시오.', '목이 말라요. 물을 (          ).', NULL, NULL, 75, '[{"id": "A", "text": "먹고 싶어요"}, {"id": "B", "text": "마시고 싶어요"}, {"id": "C", "text": "읽고 싶어요"}, {"id": "D", "text": "타고 싶어요"}]'::jsonb, '["B"]'::jsonb, 'Water is drunk: 마시다.', 'easy', ARRAY['EPS_TOPIK Reading', 'Fill in the Blank', 'daily-life']::text[], 1, TRUE, 'Text: I''m thirsty. I ____ water. Question: Choose the best answer for the blank. Choices: A. want to eat. B. want to drink. C. want to read. D. want to ride.'),
    ('eps-b2-r-blank-03', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-blank', 'Fill in the Blank', '빈칸 채우기 5', '빈칸에 들어갈 가장 알맞은 것을 고르십시오.', '비가 오니까 (          )을 가지고 가세요.', NULL, NULL, 75, '[{"id": "A", "text": "안경"}, {"id": "B", "text": "가방"}, {"id": "C", "text": "우산"}, {"id": "D", "text": "지갑"}]'::jsonb, '["C"]'::jsonb, 'Rain calls for an umbrella (우산).', 'easy', ARRAY['EPS_TOPIK Reading', 'Fill in the Blank', 'daily-life']::text[], 1, TRUE, 'Text: It''s raining, so take an ____ with you. Question: Choose the best answer for the blank. Choices: A. glasses. B. bag. C. umbrella. D. wallet.'),
    ('eps-b2-r-blank-04', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-blank', 'Fill in the Blank', '빈칸 채우기 6', '빈칸에 들어갈 가장 알맞은 것을 고르십시오.', '내일은 일요일이라서 회사에 (          ).', NULL, NULL, 75, '[{"id": "A", "text": "가요"}, {"id": "B", "text": "일해요"}, {"id": "C", "text": "출근해요"}, {"id": "D", "text": "안 가요"}]'::jsonb, '["D"]'::jsonb, 'Sunday is a day off, so 안 가요.', 'easy', ARRAY['EPS_TOPIK Reading', 'Fill in the Blank', 'workplace-culture']::text[], 1, TRUE, 'Text: Tomorrow is Sunday, so I ____ to work. Question: Choose the best answer for the blank. Choices: A. go. B. work. C. go in. D. don''t go.'),
    ('eps-b2-r-blank-05', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-blank', 'Fill in the Blank', '빈칸 채우기 7', '빈칸에 들어갈 가장 알맞은 것을 고르십시오.', '방이 너무 어두워요. 불을 (          ).', NULL, NULL, 75, '[{"id": "A", "text": "켜 주세요"}, {"id": "B", "text": "꺼 주세요"}, {"id": "C", "text": "닫아 주세요"}, {"id": "D", "text": "버려 주세요"}]'::jsonb, '["A"]'::jsonb, 'A dark room needs the light on: 켜다.', 'easy', ARRAY['EPS_TOPIK Reading', 'Fill in the Blank', 'basic-life']::text[], 1, TRUE, 'Text: The room is too dark. ____ the light. Question: Choose the best answer for the blank. Choices: A. Please turn on. B. Please turn off. C. Please close. D. Please throw away.'),
    ('eps-b2-r-blank-06', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-blank', 'Fill in the Blank', '빈칸 채우기 8', '빈칸에 들어갈 가장 알맞은 것을 고르십시오.', '햇빛이 강하니까 밖에서 일할 때는 (          )를 쓰세요.', NULL, NULL, 75, '[{"id": "A", "text": "장화"}, {"id": "B", "text": "모자"}, {"id": "C", "text": "앞치마"}, {"id": "D", "text": "넥타이"}]'::jsonb, '["B"]'::jsonb, 'You wear (쓰다) a hat on your head against the sun.', 'easy', ARRAY['EPS_TOPIK Reading', 'Fill in the Blank', 'industrial-safety']::text[], 1, TRUE, 'Text: The sun is strong, so wear a ____ when you work outside. Question: Choose the best answer for the blank. Choices: A. pair of rubber boots. B. hat. C. apron. D. tie.'),
    ('eps-b2-r-blank-07', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-blank', 'Fill in the Blank', '빈칸 채우기 9', '빈칸에 들어갈 가장 알맞은 것을 고르십시오.', '먼지가 많은 곳에서는 (          )를 써야 합니다.', NULL, NULL, 75, '[{"id": "A", "text": "모자"}, {"id": "B", "text": "넥타이"}, {"id": "C", "text": "마스크"}, {"id": "D", "text": "목도리"}]'::jsonb, '["C"]'::jsonb, 'A mask (마스크) keeps dust out of your nose and mouth.', 'easy', ARRAY['EPS_TOPIK Reading', 'Fill in the Blank', 'industrial-safety']::text[], 1, TRUE, 'Text: Where there is a lot of dust you must wear a ____. Question: Choose the best answer for the blank. Choices: A. cap. B. tie. C. face mask. D. scarf.'),
    ('eps-b2-r-blank-08', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-blank', 'Fill in the Blank', '빈칸 채우기 10', '빈칸에 들어갈 가장 알맞은 것을 고르십시오.', '한국에 온 지 일 년이 (          ).', NULL, NULL, 75, '[{"id": "A", "text": "왔어요"}, {"id": "B", "text": "갔어요"}, {"id": "C", "text": "살았어요"}, {"id": "D", "text": "되었어요"}]'::jsonb, '["D"]'::jsonb, '-ㄴ 지 … 되다 says how long it has been.', 'medium', ARRAY['EPS_TOPIK Reading', 'Fill in the Blank', 'grammar']::text[], 1, TRUE, 'Text: It ____ a year since I came to Korea. Question: Choose the best answer for the blank. Choices: A. came. B. went. C. lived. D. has been.'),
    ('eps-b2-r-blank-09', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-blank', 'Fill in the Blank', '빈칸 채우기 11', '빈칸에 들어갈 가장 알맞은 것을 고르십시오.', '저는 매일 아침 일곱 시에 (          ).', NULL, NULL, 75, '[{"id": "A", "text": "일어나요"}, {"id": "B", "text": "자요"}, {"id": "C", "text": "퇴근해요"}, {"id": "D", "text": "저녁을 먹어요"}]'::jsonb, '["A"]'::jsonb, 'Seven in the morning is when you get up.', 'easy', ARRAY['EPS_TOPIK Reading', 'Fill in the Blank', 'daily-life']::text[], 1, TRUE, 'Text: I ____ at seven every morning. Question: Choose the best answer for the blank. Choices: A. get up. B. sleep. C. leave work. D. have dinner.'),
    ('eps-b2-r-blank-10', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-blank', 'Fill in the Blank', '빈칸 채우기 12', '빈칸에 들어갈 가장 알맞은 것을 고르십시오.', '이 옷은 너무 작아요. 더 (          ) 옷 있어요?', NULL, NULL, 75, '[{"id": "A", "text": "작은"}, {"id": "B", "text": "큰"}, {"id": "C", "text": "짧은"}, {"id": "D", "text": "싼"}]'::jsonb, '["B"]'::jsonb, 'Too small, so ask for a bigger one: 큰.', 'easy', ARRAY['EPS_TOPIK Reading', 'Fill in the Blank', 'daily-life']::text[], 1, TRUE, 'Text: This is too small. Do you have a ____ one? Question: Choose the best answer for the blank. Choices: A. smaller. B. bigger. C. shorter. D. cheaper.'),
