    ('eps-b2-r-practical-22', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안전 표지: 응급 처치함', '이 표지의 뜻으로 알맞은 것은 무엇입니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_22', 75, '[{"id": "A", "text": "공구를 넣는 곳입니다."}, {"id": "B", "text": "다쳤을 때 쓰는 물건이 있습니다."}, {"id": "C", "text": "약을 파는 곳입니다."}, {"id": "D", "text": "병원 입구입니다."}]'::jsonb, '["B"]'::jsonb, '응급 처치 is first aid.', 'medium', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'industrial-safety']::text[], 1, TRUE, 'Text: First aid box. Medicine and bandages for injuries. Question: What does this sign mean? Choices: A. Tools are kept here. B. There are things for injuries here. C. Medicine is sold here. D. This is a hospital entrance.'),
    ('eps-b2-r-practical-23', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안전 표지: 대피 장소', '이 표지의 뜻으로 알맞은 것은 무엇입니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_23', 75, '[{"id": "A", "text": "주차장입니다."}, {"id": "B", "text": "운동하는 곳입니다."}, {"id": "C", "text": "위험할 때 모이는 곳입니다."}, {"id": "D", "text": "쉬는 곳입니다."}]'::jsonb, '["C"]'::jsonb, '대피 장소: where you evacuate to.', 'medium', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'industrial-safety']::text[], 1, TRUE, 'Text: Assembly point. Gather here in an earthquake or fire. Question: What does this sign mean? Choices: A. This is a car park. B. This is for exercise. C. This is where to gather in an emergency. D. This is a rest area.'),
    ('eps-b2-r-practical-24', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 회사 식당 이용 안내', '이 식당에 대한 설명으로 맞는 것은 무엇입니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_24', 75, '[{"id": "A", "text": "저녁은 일곱 시에 시작합니다."}, {"id": "B", "text": "점심시간은 두 시간입니다."}, {"id": "C", "text": "아침은 주지 않습니다."}, {"id": "D", "text": "주말에는 식당을 이용할 수 없습니다."}]'::jsonb, '["D"]'::jsonb, '※ 주말에는 쉽니다: closed at weekends.', 'easy', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'workplace-culture']::text[], 1, TRUE, 'Text: Company canteen hours. Breakfast 7–8, lunch 12–1, dinner 6–7. Closed at weekends. Question: Which is true of this canteen? Choices: A. Dinner starts at seven. B. Lunch is two hours. C. No breakfast is served. D. The canteen can''t be used at weekends.'),
    ('eps-b2-r-practical-25', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 미용실 영업 시간', '토요일에 이 미용실은 몇 시에 문을 닫습니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_25', 75, '[{"id": "A", "text": "오후 세 시"}, {"id": "B", "text": "오후 여덟 시"}, {"id": "C", "text": "오전 열 시"}, {"id": "D", "text": "문을 열지 않습니다"}]'::jsonb, '["A"]'::jsonb, '토요일 10:00~15:00: it closes at 3 p.m.', 'easy', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'daily-life']::text[], 1, TRUE, 'Text: Hair salon hours. Weekdays 10 a.m.–8 p.m. Saturday 10 a.m.–3 p.m. Closed Tuesdays. Question: What time does the salon close on Saturday? Choices: A. 3 p.m. B. 8 p.m. C. 10 a.m. D. It doesn''t open.'),
    ('eps-b2-r-practical-26', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 분리수거 안내', '종이는 언제 버립니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_26', 75, '[{"id": "A", "text": "월요일과 수요일"}, {"id": "B", "text": "화요일과 목요일"}, {"id": "C", "text": "매일"}, {"id": "D", "text": "일요일"}]'::jsonb, '["B"]'::jsonb, '화·목: 종이: paper on Tuesdays and Thursdays.', 'medium', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'basic-life']::text[], 1, TRUE, 'Text: Recycling. Mon/Wed/Fri – plastic and cans. Tue/Thu – paper. Food waste – every day. Do not put rubbish out on Sundays. Question: When does paper go out? Choices: A. Monday and Wednesday. B. Tuesday and Thursday. C. Every day. D. Sunday.'),
    ('eps-b2-r-practical-27', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 기숙사 생활 규칙', '이 규칙에 맞는 것은 무엇입니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_27', 75, '[{"id": "A", "text": "방에서 라면을 끓입니다."}, {"id": "B", "text": "밤 열두 시에 노래를 부릅니다."}, {"id": "C", "text": "외박하기 전에 미리 알립니다."}, {"id": "D", "text": "방에서 담배를 피웁니다."}]'::jsonb, '["C"]'::jsonb, '외박할 때는 미리 알리기: tell staff before an overnight stay.', 'medium', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'basic-life']::text[], 1, TRUE, 'Text: Dormitory rules. Quiet after 11 p.m. No cooking in rooms. Smoking outside only. Tell staff in advance if you stay out overnight. Question: Which follows these rules? Choices: A. Cooking noodles in your room. B. Singing at midnight. C. Telling staff before staying out overnight. D. Smoking in your room.'),
    ('eps-b2-r-practical-28', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 통근 버스 시간표', '기숙사에서 공장까지 얼마나 걸립니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_28', 75, '[{"id": "A", "text": "이십 분"}, {"id": "B", "text": "한 시간"}, {"id": "C", "text": "십 분"}, {"id": "D", "text": "삼십 분"}]'::jsonb, '["D"]'::jsonb, '7:20 to 7:50 is thirty minutes.', 'medium', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'numbers-time']::text[], 1, TRUE, 'Text: Shuttle bus timetable. Leaves dorm 7:20, arrives factory 7:50. Leaves factory 18:10, arrives dorm 18:40. Question: How long does it take from the dormitory to the factory? Choices: A. Twenty minutes. B. An hour. C. Ten minutes. D. Thirty minutes.'),
    ('eps-b2-r-practical-29', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 건강 검진 안내', '건강 검진에 대한 설명으로 맞는 것은 무엇입니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_29', 75, '[{"id": "A", "text": "검진 전날 밤부터 음식을 먹으면 안 됩니다."}, {"id": "B", "text": "검진은 오후에 합니다."}, {"id": "C", "text": "검진은 병원에서 합니다."}, {"id": "D", "text": "검진은 목요일에 합니다."}]'::jsonb, '["A"]'::jsonb, '※ 전날 밤부터 금식: fast from the night before.', 'medium', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'public-services']::text[], 1, TRUE, 'Text: Health check. Date – Wednesday 20 May. Time – 9 a.m.–12 noon. Place – 2nd floor meeting room. No food from the night before. Question: Which is true of the health check? Choices: A. No eating from the night before. B. It''s in the afternoon. C. It''s at a hospital. D. It''s on Thursday.'),
    ('eps-b2-r-practical-30', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 휴가 신청 방법', '휴가를 신청할 때 두 번째로 하는 일은 무엇입니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_30', 75, '[{"id": "A", "text": "신청서를 씁니다."}, {"id": "B", "text": "반장님 사인을 받습니다."}, {"id": "C", "text": "사무실에 냅니다."}, {"id": "D", "text": "사장님께 전화합니다."}]'::jsonb, '["B"]'::jsonb, '② 반장님 사인 받기 is step two.', 'medium', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'workplace-culture']::text[], 1, TRUE, 'Text: How to apply for leave. 1. Fill in the form. 2. Get the team leader''s signature. 3. Hand it in at the office. At least one week before. Question: What is the second step in applying for leave? Choices: A. Fill in the form. B. Get the team leader''s signature. C. Hand it to the office. D. Phone the boss.'),
    ('eps-b2-r-practical-31', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 한국어 교실', '이 수업에 대한 설명으로 맞는 것은 무엇입니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_31', 75, '[{"id": "A", "text": "수업은 토요일에 합니다."}, {"id": "B", "text": "수업료를 내야 합니다."}, {"id": "C", "text": "교재를 사지 않아도 됩니다."}, {"id": "D", "text": "수업은 세 시간입니다."}]'::jsonb, '["C"]'::jsonb, '교재 무료 제공: textbooks are free.', 'easy', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'daily-life']::text[], 1, TRUE, 'Text: Korean class. Every Sunday 2–4 p.m. Civic Centre, 3rd floor. Free for foreign workers. Textbooks provided free. Question: Which is true of this class? Choices: A. Classes are on Saturdays. B. There''s a fee. C. You don''t need to buy the textbook. D. Classes last three hours.'),
    ('eps-b2-r-practical-32', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 엘리베이터 점검', '오후 세 시에 이 건물에서 어떻게 올라갑니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_32', 75, '[{"id": "A", "text": "엘리베이터를 탑니다."}, {"id": "B", "text": "올라갈 수 없습니다."}, {"id": "C", "text": "에스컬레이터를 탑니다."}, {"id": "D", "text": "계단으로 올라갑니다."}]'::jsonb, '["D"]'::jsonb, '3 p.m. falls in the 2–4 p.m. inspection, so take the stairs.', 'medium', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'basic-life']::text[], 1, TRUE, 'Text: Lift inspection. Today 2–4 p.m. The lift cannot be used. Please use the stairs. Question: How do you go up in this building at 3 p.m.? Choices: A. By lift. B. You can''t go up. C. By escalator. D. By the stairs.'),
    ('eps-b2-r-practical-33', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 택배 보관 안내', '택배를 찾을 수 있는 시간은 언제입니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_33', 75, '[{"id": "A", "text": "저녁 여섯 시부터 열 시까지"}, {"id": "B", "text": "아침 여섯 시부터"}, {"id": "C", "text": "하루 종일"}, {"id": "D", "text": "밤 열 시 이후"}]'::jsonb, '["A"]'::jsonb, '찾는 시간: 18:00~22:00.', 'easy', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'basic-life']::text[], 1, TRUE, 'Text: Parcel storage. Parcels are kept at the security office. Collection – 6–10 p.m. Name and room number checked. Question: When can parcels be collected? Choices: A. 6 to 10 p.m. B. From 6 a.m. C. All day. D. After 10 p.m.'),
    ('eps-b2-r-practical-34', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 버스 요금', '어른이 교통카드로 내면 얼마입니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_34', 75, '[{"id": "A", "text": "1,600원"}, {"id": "B", "text": "1,500원"}, {"id": "C", "text": "800원"}, {"id": "D", "text": "무료"}]'::jsonb, '["B"]'::jsonb, '교통카드 1,500원.', 'easy', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'numbers-time']::text[], 1, TRUE, 'Text: Bus fares. Transport card 1,500 won. Cash 1,600 won. Children 800 won. Transfer discount with card only. Question: How much does an adult pay by transport card? Choices: A. 1,600 won. B. 1,500 won. C. 800 won. D. Free.'),
    ('eps-b2-r-practical-35', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 도서관 이용 안내', '이 도서관에 대한 설명으로 맞는 것은 무엇입니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_35', 75, '[{"id": "A", "text": "일요일에는 쉽니다."}, {"id": "B", "text": "책을 열 권 빌릴 수 있습니다."}, {"id": "C", "text": "월요일에는 문을 열지 않습니다."}, {"id": "D", "text": "밤 아홉 시에 문을 닫습니다."}]'::jsonb, '["C"]'::jsonb, '※ 월요일 휴관: closed Mondays.', 'easy', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'public-services']::text[], 1, TRUE, 'Text: Library. Tuesday–Sunday 9 a.m.–6 p.m. Closed Mondays. Loans – 5 books for 2 weeks. Question: Which is true of this library? Choices: A. It''s closed on Sundays. B. You can borrow ten books. C. It''s closed on Mondays. D. It closes at 9 p.m.'),
    ('eps-b2-r-practical-36', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 세탁실 이용 요금', '세탁기와 건조기를 모두 쓰면 얼마입니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_36', 75, '[{"id": "A", "text": "3,000원"}, {"id": "B", "text": "2,000원"}, {"id": "C", "text": "6,000원"}, {"id": "D", "text": "5,000원"}]'::jsonb, '["D"]'::jsonb, '3,000 + 2,000 = 5,000 won.', 'medium', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'numbers-time']::text[], 1, TRUE, 'Text: Laundry room. Washer 3,000 won (50 min). Dryer 2,000 won (40 min). Coins only. Question: How much to use both the washer and the dryer? Choices: A. 3,000 won. B. 2,000 won. C. 6,000 won. D. 5,000 won.'),
    ('eps-b2-r-practical-37', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 공장 견학 안내', '견학할 때 해야 하는 것은 무엇입니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_37', 75, '[{"id": "A", "text": "안전모를 씁니다."}, {"id": "B", "text": "사진을 찍습니다."}, {"id": "C", "text": "두 시간 동안 봅니다."}, {"id": "D", "text": "저녁에 갑니다."}]'::jsonb, '["A"]'::jsonb, '※ 안전모 착용 필수: a helmet is required.', 'medium', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'industrial-safety']::text[], 1, TRUE, 'Text: Factory tours. Times – 10:00 and 14:00. Length – 1 hour. Safety helmet required. No photography. Question: What must you do on the tour? Choices: A. Wear a helmet. B. Take photos. C. Watch for two hours. D. Go in the evening.'),
    ('eps-b2-r-practical-38', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 고용센터 상담 안내', '이 안내문의 내용과 같은 것을 고르십시오.', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_38', 75, '[{"id": "A", "text": "일요일에도 상담합니다."}, {"id": "B", "text": "토요일 오전에도 상담할 수 있습니다."}, {"id": "C", "text": "상담료를 내야 합니다."}, {"id": "D", "text": "영어 통역만 있습니다."}]'::jsonb, '["B"]'::jsonb, '토요일 10:00~13:00: open Saturday morning.', 'medium', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'laws-systems']::text[], 1, TRUE, 'Text: Job centre advice. Weekdays 9 a.m.–6 p.m. Saturday 10 a.m.–1 p.m. Interpreting – Vietnamese, Nepali. Advice is free. Question: Which matches the notice? Choices: A. Advice is given on Sundays. B. Advice is available on Saturday morning. C. You must pay for advice. D. Only English interpreting.'),
    ('eps-b2-r-practical-39', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 단수 안내', '이 안내문을 보고 미리 해야 할 일은 무엇입니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_39', 75, '[{"id": "A", "text": "전기를 끕니다."}, {"id": "B", "text": "창문을 닫습니다."}, {"id": "C", "text": "물을 받아 둡니다."}, {"id": "D", "text": "가스를 잠급니다."}]'::jsonb, '["C"]'::jsonb, '※ 미리 물을 받아 두세요: store water beforehand.', 'medium', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'basic-life']::text[], 1, TRUE, 'Text: Water cut. Tuesday 3 May, 9 a.m.–3 p.m. There will be no water. Please store some water in advance. Question: What should you do in advance? Choices: A. Turn off the electricity. B. Close the windows. C. Store some water. D. Turn off the gas.'),
    ('eps-b2-r-practical-40', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 회사 체육 대회', '체육 대회에 대한 설명으로 맞는 것은 무엇입니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_40', 75, '[{"id": "A", "text": "회사 안에서 합니다."}, {"id": "B", "text": "일요일에 합니다."}, {"id": "C", "text": "농구를 합니다."}, {"id": "D", "text": "점심을 줍니다."}]'::jsonb, '["D"]'::jsonb, '※ 점심 제공: lunch is provided.', 'easy', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'workplace-culture']::text[], 1, TRUE, 'Text: Company sports day. Saturday 12 October. Place – Civic Stadium. Events – football, tug of war. Lunch provided. Question: Which is true of the sports day? Choices: A. It''s held at the company. B. It''s on Sunday. C. There''s basketball. D. Lunch is provided.'),
    ('eps-b2-r-practical-41', 'eps-topik-2026-01', 'EPS_TOPIK', ARRAY['EPS_TOPIK'], 'reading', 'eps-r-practical', 'Signs, Notices and Charts', '안내문: 월급 명세서', '이 사람이 통장으로 받는 돈은 얼마입니까?', NULL, NULL, '/api/v1/questions/assets/eps_b2_sign_41', 75, '[{"id": "A", "text": "2,200,000원"}, {"id": "B", "text": "2,100,000원"}, {"id": "C", "text": "2,400,000원"}, {"id": "D", "text": "300,000원"}]'::jsonb, '["A"]'::jsonb, '실수령액 (take-home pay) is 2,200,000 won.', 'hard', ARRAY['EPS_TOPIK Reading', 'Signs, Notices and Charts', 'job-korean']::text[], 1, TRUE, 'Text: Payslip. Basic pay 2,100,000 won. Overtime 300,000 won. Deductions −200,000 won. Take-home pay 2,200,000 won. Question: How much does this person receive in their account? Choices: A. 2,200,000 won. B. 2,100,000 won. C. 2,400,000 won. D. 300,000 won.'),
