-- English versions for the starter reading questions, which had none.
UPDATE questions AS q SET audio_translation = t.english
FROM (VALUES
    ('eps-seed-r-picture-1', 'Question: Look at the picture and choose the matching word or sentence. Choices: A. It''s a hammer. B. They''re scissors. C. It''s an umbrella. D. It''s a clock.'),
    ('eps-seed-r-picture-2', 'Question: Look at the picture and choose the matching word or sentence. Choices: A. They''re socks. B. They''re gloves. C. They''re glasses. D. It''s a bag.'),
    ('eps-seed-r-grammar-1', 'Question: Which underlined part is correct? Choices: A. I eat an apple. B. I meet a friend. C. I go to the factory. D. I rest at the weekend.'),
    ('eps-seed-r-grammar-2', 'Question: Which underlined part is correct? Choices: A. I listen to music. B. The weather is hot. C. I closed the window. D. The noodles are spicy.'),
    ('eps-seed-r-practical-1', 'Text: Happy Pharmacy. Opening hours 9 a.m. to 7 p.m. Closed on Sundays. Phone 031-123-4567. Danwon-gu, Ansan, Gyeonggi-do. Question: When is this pharmacy closed? Choices: A. Saturday. B. Sunday. C. Monday. D. It opens every day.'),
    ('eps-seed-r-practical-2', 'Text: Caution – electric shock. Question: What does this sign mean? Choices: A. You could get an electric shock. B. The floor is slippery. C. You may not smoke. D. You must wear a safety helmet.'),
    ('eps-seed-r-word-1', 'Text: Monthly salary. Question: Which is related to this word? Choices: A. Money you are paid by the company. B. Food you eat at the company. C. Clothes you wear at the company. D. A room you sleep in at the company.'),
    ('eps-seed-r-word-2', 'Text: Dormitory. Question: Which is related to this word? Choices: A. The place where workers work. B. The place where workers take out money. C. The place where workers live. D. The place where workers buy food.'),
    ('eps-seed-r-blank-1', 'Text: It''s cold, so ____ thick clothes. Question: Choose the best answer for the blank. Choices: A. wear. B. eat. C. ride. D. read.'),
    ('eps-seed-r-blank-2', 'Text: Before cleaning the machine, you must ____ the power. Question: Choose the best answer for the blank. Choices: A. turn on. B. turn off. C. buy. D. borrow.'),
    ('eps-seed-r-def-1', 'Text: A tool used to cut wood or metal. Its blade has many sharp teeth. Question: Choose the word that fits the description. Choices: A. saw. B. hammer. C. screwdriver. D. tape measure.'),
    ('eps-seed-r-def-2', 'Text: A tool for measuring length. It stretches when you pull it and winds back in when you press the button. Question: Choose the word that fits the description. Choices: A. pliers. B. tape measure. C. shovel. D. brush.'),
    ('eps-seed-r-topic-1', 'Text: In Korea people eat rice cake soup at New Year. People believe eating it makes you a year older. Families also gather and bow to their elders. Question: Read the text and choose what it is about. Choices: A. New Year customs. B. Food prices. C. Travel plans. D. Changes in the weather.'),
    ('eps-seed-r-topic-2', 'Text: To avoid getting hurt at work you must follow the rules. Wear protective equipment before work, and keep your hands out of a moving machine. Also wipe up any water on the floor straight away. Question: Read the text and choose what it is about. Choices: A. Applying for leave. B. Safety rules. C. Working out pay. D. Where the staff dinner is.'),
    ('eps-seed-r-detail-1', 'Text: Our company canteen is open from 7 to 8 in the morning and from 12 to 1 at lunchtime. Dinner is not served. To use the canteen you must show your staff card. Question: Read the text and choose the statement that matches it. Choices: A. You can eat dinner in the canteen. B. The lunch break is one hour. C. The canteen is open all day. D. You can use the canteen without a staff card.'),
    ('eps-seed-r-detail-2', 'Text: A foreign worker who wants to change company must apply to the job centre. The number of times you can change company is limited. After changing, you must sign a new employment contract with the new company. Question: Read the text and choose the statement that matches it. Choices: A. You don''t need to apply when changing company. B. You can change company as often as you like. C. You must sign a new contract with the new company. D. You only ever sign one contract.'),
    ('eps-seed-r-ttp-1', 'Text: You use it on rainy days. You open it and hold it over your head. Question: Read the description and choose the matching picture. Choices: A. umbrella. B. cap. C. gloves. D. glasses.'),
    ('eps-seed-r-ttp-2', 'Text: When there is a fire, you put it out with this. Pull out the safety pin and squeeze the handle. Question: Read the description and choose the matching picture. Choices: A. hammer. B. telephone. C. fire extinguisher. D. ladder.')
) AS t(id, english)
WHERE q.id = t.id AND COALESCE(q.audio_translation, '') = '';

-- Starter titles that named the answer. Only a title nobody has changed is replaced.
UPDATE questions AS q SET title = t.new_title
FROM (VALUES
    ('eps-seed-r-picture-1', '공구 이름: 망치', '그림 보고 고르기 1'),
    ('eps-seed-r-picture-2', '보호 장비: 장갑', '그림 보고 고르기 2'),
    ('eps-seed-r-blank-1', '빈칸: 옷을 입다', '빈칸 채우기 1'),
    ('eps-seed-r-blank-2', '빈칸: 전원을 끄다', '빈칸 채우기 2'),
    ('eps-seed-r-def-1', '도구 설명: 톱', '설명에 맞는 어휘 1'),
    ('eps-seed-r-def-2', '도구 설명: 줄자', '설명에 맞는 어휘 2'),
    ('eps-seed-r-topic-1', '글의 주제: 설날', '글의 주제 1'),
    ('eps-seed-r-topic-2', '글의 주제: 안전 수칙', '글의 주제 2'),
    ('eps-seed-r-ttp-1', '설명: 우산', '설명 보고 그림 고르기 1'),
    ('eps-seed-r-ttp-2', '설명: 소화기', '설명 보고 그림 고르기 2'),
    ('eps-seed-l-sound-1', '소리 구별: 공장', '소리 구별 1'),
    ('eps-seed-l-sound-2', '소리 구별: 시장', '소리 구별 2'),
    ('eps-seed-l-picture-1', '그림 고르기: 우유', '듣고 그림 고르기 1'),
    ('eps-seed-l-picture-2', '그림 고르기: 상자 옮기기', '듣고 그림 고르기 2'),
    ('eps-seed-l-pq-1', '위치: 가방', '그림 보고 대답하기 1'),
    ('eps-seed-l-pq-2', '시간: 세 시', '그림 보고 대답하기 2')
) AS t(id, old_title, new_title)
